// --- UTILITY FUNCTIONS ---
const isOverlapping = (f1: Omit<ScheduleEvent, 'date'>, f2: Omit<ScheduleEvent, 'date'>): boolean => {
    if (!f1 || !f2 || f1.duration <= 0 || f2.duration <= 0) return false;
    const f1_end = f1.startTime + f1.duration;
    const f2_end = f2.startTime + f2.duration;
    return f1.startTime < f2_end && f1_end > f2.startTime;
};

const getPersonnel = (event: Omit<ScheduleEvent, 'date'> | ScheduleEvent): string[] => {
    const personnel = new Set<string>();

    const isTaskingEvent = event.isTaskingRequest === true || !!event.taskingRequestId || String(event.id || '').startsWith('tasking-');
    const isSctEvent = event.flightNumber?.startsWith('SCT');

    if (isTaskingEvent) {
        if (event.pilot) personnel.add(event.pilot);
        if (event.crew) personnel.add(event.crew);
        if (event.instructor) personnel.add(event.instructor);
    } else if (isSctEvent) {
        // For SCT events: pilot (PIC) + crew (second pilot)
        if (event.pilot) personnel.add(event.pilot);
        if (event.crew) personnel.add(event.crew);
    } else if (event.flightType === 'Solo') {
        if (event.pilot) personnel.add(event.pilot);
    } else {
        // For non-SCT Dual training events, the instructor field is authoritative.
        // The pilot field is a legacy mirror of instructor and may be stale after crew swaps.
        if (event.instructor) personnel.add(event.instructor);
        else if (event.pilot) personnel.add(event.pilot);
        if (event.student) personnel.add(event.student);
    }

    if (event.attendees) event.attendees.forEach(p => personnel.add(p));
    if (event.groupTraineeIds && event.groupTraineeIds.length > 0) {
        // In a real app you'd resolve these IDs to names, but for conflict checks, the presence of people is enough.
        // For now, let's assume if there are group IDs, the main people are already in instructor/student fields for conflict checks.
        // This function is mainly for conflict detection, not display.
    }
    return Array.from(personnel);
};

const PERSONNEL_RANK_PREFIX_RE = /^(ACM|AIRMSHL|AVM|AIRCDRE|GPCAPT|WGCDR|SQNLDR|FLTLT|FLGOFF|PLTOFF|OFFCDT|WOFF|FSGT|SGT|CPL|LACW?|ACW?|MIDN|CMDR|LCDR|LEUT|SBLT|ASLT|CDRE|CAPT|COL|LTCOL|MAJ|LT|2LT|WO1|WO2|SSGT|PTE|MR|MRS|MS|MISS|DR)\s+/i;

const normalizePersonnelNameForMatch = (name?: string): string =>
    (name || '')
        .replace(/\s+/g, ' ')
        .trim()
        .replace(PERSONNEL_RANK_PREFIX_RE, '')
        .replace(/\s+[–-]\s+[A-Z]{2,}\d+$/i, '')
        .toLowerCase();

const personnelNamesMatch = (a?: string, b?: string): boolean => {
    const left = normalizePersonnelNameForMatch(a);
    const right = normalizePersonnelNameForMatch(b);
    return !!left && left === right;
};

const isNeoBuildVerboseDiagnosticsEnabled = (): boolean =>
    typeof window !== 'undefined' && window.localStorage?.getItem('neo_build_verbose_diag') === 'true';

interface NeoBuildTimingPhase {
    name: string;
    durationMs: number;
    totalElapsedMs: number;
    details?: Record<string, any>;
}

interface NeoBuildTimingReport {
    timestamp: string;
    buildDate: string;
    phases: NeoBuildTimingPhase[];
    counters: Record<string, any>;
    startedAtMs?: number;
    lastMarkMs?: number;
    completedAt?: string;
    totalElapsedMs?: number;
}

const createNeoBuildTimingReport = (buildDate: string, counters: Record<string, any> = {}): NeoBuildTimingReport => {
    const now = performance.now();
    return {
        timestamp: new Date().toISOString(),
        buildDate,
        phases: [],
        counters,
        startedAtMs: now,
        lastMarkMs: now,
    };
};

const saveNeoBuildTimingReport = (report?: NeoBuildTimingReport) => {
    if (!report) return;
    try {
        localStorage.setItem('neo_build_timing_report', JSON.stringify(report));
    } catch (error) {
        console.warn('[NEO-BUILD-TIMING] Failed to save timing report:', error);
    }
};

const markNeoBuildTiming = (
    report: NeoBuildTimingReport | undefined,
    name: string,
    details?: Record<string, any>
) => {
    if (!report || report.startedAtMs === undefined || report.lastMarkMs === undefined) return;
    const now = performance.now();
    report.phases.push({
        name,
        durationMs: Math.round(now - report.lastMarkMs),
        totalElapsedMs: Math.round(now - report.startedAtMs),
        ...(details ? { details } : {}),
    });
    report.lastMarkMs = now;
    report.completedAt = new Date().toISOString();
    report.totalElapsedMs = Math.round(now - report.startedAtMs);
    saveNeoBuildTimingReport(report);
};

type PersonnelIdentityRole = 'staff' | 'trainee';

interface PersonnelIdentityRef {
    label: string;
    role: PersonnelIdentityRole;
    key: string;
}

const makePersonnelIdentityRef = (label: string | undefined, role: PersonnelIdentityRole): PersonnelIdentityRef | null => {
    const normalizedName = normalizePersonnelNameForMatch(label);
    if (!normalizedName) return null;
    return {
        label: label || '',
        role,
        key: `${role}:${normalizedName}`
    };
};

const getPersonnelIdentityRefs = (event: Omit<ScheduleEvent, 'date'> | ScheduleEvent): PersonnelIdentityRef[] => {
    const refsByKey = new Map<string, PersonnelIdentityRef>();
    const addRef = (label: string | undefined, role: PersonnelIdentityRole) => {
        const ref = makePersonnelIdentityRef(label, role);
        if (ref && !refsByKey.has(ref.key)) refsByKey.set(ref.key, ref);
    };

    const isSctEvent = event.flightNumber?.startsWith('SCT');

    if (isSctEvent) {
        addRef(event.pilot, 'staff');
        addRef(event.crew, 'staff');
    } else if (event.flightType === 'Solo') {
        addRef(event.pilot || event.student, 'trainee');
    } else {
        addRef(event.instructor || event.pilot, 'staff');
        addRef(event.student, 'trainee');
    }

    event.attendees?.forEach(personName => addRef(personName, 'trainee'));
    return Array.from(refsByKey.values());
};

const eventHasPersonWithRole = (
    event: Omit<ScheduleEvent, 'date'> | ScheduleEvent,
    personName: string | undefined,
    role: PersonnelIdentityRole
): boolean => {
    const ref = makePersonnelIdentityRef(personName, role);
    if (!ref) return false;
    return getPersonnelIdentityRefs(event).some(eventRef => eventRef.key === ref.key);
};

const eventHasPerson = (
    event: Omit<ScheduleEvent, 'date'> | ScheduleEvent,
    personName?: string
): boolean => getPersonnel(event).some(p => personnelNamesMatch(p, personName));

const getCommonPersonnel = (
    eventA: Omit<ScheduleEvent, 'date'> | ScheduleEvent,
    eventB: Omit<ScheduleEvent, 'date'> | ScheduleEvent
): string[] => {
    const eventBPersonnelKeys = new Set(getPersonnelIdentityRefs(eventB).map(person => person.key));
    return getPersonnelIdentityRefs(eventA)
        .filter(person => eventBPersonnelKeys.has(person.key))
        .map(person => person.label);
};

const normaliseCrewFieldsForSave = (event: ScheduleEvent): ScheduleEvent => {
    const normalised = { ...event };
    const isSctEvent = normalised.eventCategory === 'sct' || normalised.flightNumber?.startsWith('SCT');

    if (isSctEvent) {
        normalised.instructor = '';
        return normalised;
    }

    if ((normalised.type === 'flight' || normalised.type === 'ftd') && normalised.flightType === 'Solo') {
        normalised.pilot = normalised.pilot || normalised.student || '';
        normalised.instructor = '';
        normalised.student = '';
        return normalised;
    }

    if ((normalised.type === 'flight' || normalised.type === 'ftd') && normalised.instructor) {
        normalised.pilot = normalised.instructor;
    }

    return normalised;
};

const isDutySupervisorEvent = (event: Omit<ScheduleEvent, 'date'> | ScheduleEvent): boolean =>
    event.flightNumber === 'Duty Sup' ||
    event.flightNumber === 'Night Duty Sup' ||
    event.resourceId === 'Duty Sup';

const isStbyResource = (resourceId?: string): boolean =>
    !!resourceId && (resourceId.startsWith('STBY') || resourceId.startsWith('BNF-STBY'));

const getEventBookingWindow = (
    event: ScheduleEvent,
    syllabusDetails: SyllabusItemDetail[]
): { start: number, end: number } => {
    const syllabusItem = syllabusDetails.find(s => s.id === event.flightNumber || s.code === event.flightNumber);
    const preFlightTime = syllabusItem?.preFlightTime ?? event.preStart ?? 0;
    const postFlightTime = syllabusItem?.postFlightTime ?? event.postEnd ?? 0;
    return {
        start: event.startTime - preFlightTime,
        end: event.startTime + event.duration + postFlightTime,
    };
};

const getEventBookingWindowForAlgo = (
    event: Omit<ScheduleEvent, 'date'> | { startTime: number, flightNumber: string, duration: number, preStart?: number, postEnd?: number },
    syllabusDetails: SyllabusItemDetail[]
): { start: number, end: number } => {
    const syllabusItem = syllabusDetails.find(s => s.id === event.flightNumber || s.code === event.flightNumber);
    const preFlightTime = syllabusItem?.preFlightTime ?? event.preStart ?? 0;
    const postFlightTime = syllabusItem?.postFlightTime ?? event.postEnd ?? 0;
    return {
        start: event.startTime - preFlightTime,
        end: event.startTime + event.duration + postFlightTime,
    };
};

/**
 * Determines if an event is a Day or Night event based on the Master LMP Day/Night field
 * @param event - The event to check
 * @param syllabusDetails - The syllabus details containing Day/Night classification
 * @returns 'Day', 'Night', or 'Day/Night' based on the syllabus classification
 */
const getEventDayNightClassification = (
    event: { flightNumber: string; dayNight?: 'Day' | 'Night' | 'Day/Night' },
    syllabusDetails: SyllabusItemDetail[],
    sctEvents?: string[]
): 'Day' | 'Night' | 'Day/Night' => {
    if (event.dayNight) {
        return event.dayNight;
    }

    if (event.flightNumber === 'Night Duty Sup') {
        return 'Night';
    }
    if (event.flightNumber === 'Duty Sup') {
        return 'Day';
    }

    // Check for SCT events first (since they're not in Master LMP)
    if (sctEvents && sctEvents.includes(event.flightNumber)) {
        // Night SCT is specifically a night event
        if (event.flightNumber === 'Night SCT') {
            return 'Night';
        }
        // All other SCT events default to Day
        return 'Day';
    }

    const syllabusItem = syllabusDetails.find(s => s.id === event.flightNumber || s.code === event.flightNumber);
    if (syllabusItem && syllabusItem.dayNight) {
        return syllabusItem.dayNight;
    }
    // Default to Day if not found or not specified
    return 'Day';
};

const getMasterEventId = (item: Partial<SyllabusItemDetail>): string =>
    item.masterEventId || item.id || item.code || '';

const createLmpOrderKey = (index: number): string => String(index + 1).padStart(5, '0');
const REMEDIAL_EARLIEST_START = 10.0;
const REMEDIAL_FORCE_SCHEDULE_STORAGE_KEY = 'neo_remedial_force_schedule_requests';
const ACTIVE_OPERATIONAL_CONTEXT_STORAGE_KEY = 'dfp_active_operational_context';
const ACTIVE_OPERATIONAL_CONTEXT_DIAG_KEY = 'neo_context_selector_diag';
const REMEDIAL_EVENT_CODE_REGEX = /-(?:REM-[A-Z]+\d+|RFTD\d+|RRF\d+|RT\d+|RF\d+|FTD\d+|F\d+|T\d+)$/i;

const isRemedialEventCode = (value?: string): boolean =>
    !!value && REMEDIAL_EVENT_CODE_REGEX.test(value);

const getRemedialBaseEventCode = (item: Partial<SyllabusItemDetail>): string =>
    String(item.code || item.id || item.masterEventId || '').replace(REMEDIAL_EVENT_CODE_REGEX, '');

const isRemedialSyllabusItem = (item?: Partial<SyllabusItemDetail>): boolean =>
    !!item && (
        item.lmpSource === 'remedial' ||
        item.isRemedial === true ||
        isRemedialEventCode(item.id) ||
        isRemedialEventCode(item.code)
    );

const normaliseRemedialRequests = (value: unknown): RemedialRequest[] => {
    if (!Array.isArray(value)) return [];
    return value
        .map((item: any) => ({
            traineeId: Number(item?.traineeId),
            eventCode: String(item?.eventCode || ''),
            forceSchedule: item?.forceSchedule === true,
            aircraftConfigId: String(item?.aircraftConfigId || BASE_AIRCRAFT_CONFIG.id),
        }))
        .filter(item => Number.isFinite(item.traineeId) && item.eventCode && item.forceSchedule);
};

const loadStoredRemedialRequests = (): RemedialRequest[] => {
    try {
        return normaliseRemedialRequests(JSON.parse(localStorage.getItem(REMEDIAL_FORCE_SCHEDULE_STORAGE_KEY) || '[]'));
    } catch {
        return [];
    }
};

const storeRemedialRequests = (requests: RemedialRequest[]) => {
    try {
        localStorage.setItem(
            REMEDIAL_FORCE_SCHEDULE_STORAGE_KEY,
            JSON.stringify(normaliseRemedialRequests(requests))
        );
    } catch (error) {
        console.warn('[REMEDIAL-SYNC] Failed to persist Force Schedule selections:', error);
    }
};

const stampMasterLmpItems = (masterLMP: SyllabusItemDetail[]): SyllabusItemDetail[] =>
    masterLMP.map((item, index) => ({
        ...item,
        masterEventId: getMasterEventId(item),
        lmpSource: 'master',
        orderKey: item.orderKey || createLmpOrderKey(index),
        notes: item.notes || '',
        placementNeedsReview: false,
    }));

const isLmpOverlayItem = (item: SyllabusItemDetail): boolean =>
    item.lmpSource === 'remedial' ||
    item.lmpSource === 'custom' ||
    item.isRemedial === true ||
    item.id?.includes('REM') ||
    isRemedialEventCode(item.id) ||
    item.code?.includes('REM') ||
    isRemedialEventCode(item.code) ||
    item.id?.endsWith('-CUR') ||
    item.code?.endsWith('-CUR');

const getLmpResourceNumber = (item?: Partial<SyllabusItemDetail> | null): number => {
    const resourceCountAlias = (item as any)?.resourceCount;
    const parsed = Number(item?.resourceNumber ?? resourceCountAlias);
    if (Number.isFinite(parsed) && parsed > 1) return Math.max(1, Math.round(parsed));

    const physicalResourceCount = Array.isArray(item?.resourcesPhysical)
        ? item.resourcesPhysical.filter(resource => String(resource || '').trim().length > 0).length
        : 0;
    if (physicalResourceCount > 1) return physicalResourceCount;

    const eventCode = String(item?.code || item?.id || item?.masterEventId || '').trim().toUpperCase();
    if (item?.type === 'Flight' && /^FORM/.test(eventCode)) return 2;

    return Number.isFinite(parsed) ? Math.max(1, Math.round(parsed)) : 1;
};

const isMultiResourceFlightItem = (item?: Partial<SyllabusItemDetail> | null): boolean =>
    !!item && item.type === 'Flight' && getLmpResourceNumber(item) > 1;

const alignPhysicalResourcesToResourceNumber = (
    resourcesPhysical: string[] | undefined,
    resourceNumber: number,
    resourceLabel = 'Aircraft'
): string[] => {
    const count = Math.max(0, Math.round(Number(resourceNumber) || 0));
    const existing = (resourcesPhysical || []).filter(resource => String(resource || '').trim().length > 0);
    if (count === 0) return existing;

    const aligned = existing.slice(0, count);
    for (let index = aligned.length; index < count; index++) {
        aligned.push(count === 1 ? resourceLabel : `${resourceLabel} ${index + 1}`);
    }
    return aligned;
};

const getFormationEventKey = (item?: Partial<SyllabusItemDetail> | null): string =>
    String(item?.code || item?.masterEventId || item?.id || '')
        .trim()
        .toUpperCase()
        .replace(/\s+/g, '');

const INDIVIDUAL_LMP_EDITABLE_FIELDS: (keyof SyllabusItemDetail)[] = [
    'code',
    'eventDescription',
    'phase',
    'module',
    'type',
    'sortieType',
    'dayNight',
    'methodOfDelivery',
    'methodOfAssessment',
    'resourcesPhysical',
    'resourceNumber',
    'resourcesHuman',
    'eventDetailsCommon',
    'eventDetailsSortie',
    'flightOrSimHours',
    'totalEventHours',
    'duration',
    'preFlightTime',
    'postFlightTime',
    'prerequisites',
    'prerequisitesGround',
    'prerequisitesFlying',
    'location',
    'twrDiReqd',
    'cctOnly',
    'notes',
];

const getIndividualLmpMasterOverrides = (item?: SyllabusItemDetail): Partial<SyllabusItemDetail> => {
    if (!item) return {};
    return INDIVIDUAL_LMP_EDITABLE_FIELDS.reduce((overrides, field) => {
        if (Object.prototype.hasOwnProperty.call(item, field)) {
            (overrides as any)[field] = (item as any)[field];
        }
        return overrides;
    }, {} as Partial<SyllabusItemDetail>);
};

const mergeIndividualLmpWithMaster = (
    existingLmp: SyllabusItemDetail[] | undefined,
    masterLMP: SyllabusItemDetail[]
): SyllabusItemDetail[] => {
    const stampedMaster = stampMasterLmpItems(masterLMP);
    if (!existingLmp || existingLmp.length === 0) return stampedMaster;

    const masterIds = new Set(stampedMaster.map(getMasterEventId).filter(Boolean));
    const existingByMasterId = new Map<string, SyllabusItemDetail>();
    existingLmp.forEach(item => {
        if (isLmpOverlayItem(item)) return;
        const masterId = getMasterEventId(item);
        if (masterId) existingByMasterId.set(masterId, item);
    });

    const mergedMaster = stampedMaster.map((masterItem, index) => {
        const existingItem = existingByMasterId.get(getMasterEventId(masterItem));
        return {
            ...masterItem,
            ...getIndividualLmpMasterOverrides(existingItem),
            id: masterItem.id,
            masterEventId: getMasterEventId(masterItem),
            lmpSource: 'master',
            completedAt: (existingItem as any)?.completedAt ?? (masterItem as any).completedAt ?? null,
            userLockedPosition: existingItem?.userLockedPosition,
            orderKey: existingItem?.orderKey || masterItem.orderKey || createLmpOrderKey(index),
            placementNeedsReview: false,
        } as SyllabusItemDetail;
    });

    const masterIndexById = new Map<string, number>();
    mergedMaster.forEach((item, index) => {
        const masterId = getMasterEventId(item);
        if (masterId) masterIndexById.set(masterId, index);
    });

    const overlays = existingLmp.filter(isLmpOverlayItem).map((item, index) => {
        const itemIndex = existingLmp.indexOf(item);
        const fallbackAfter = item.anchorAfterMasterEventId || getMasterEventId(existingLmp.slice(0, itemIndex).reverse().find(prev => !isLmpOverlayItem(prev)) || {});
        const fallbackBefore = item.anchorBeforeMasterEventId || getMasterEventId(existingLmp.slice(itemIndex + 1).find(next => !isLmpOverlayItem(next)) || {});
        const afterExists = !!fallbackAfter && masterIds.has(fallbackAfter);
        const beforeExists = !!fallbackBefore && masterIds.has(fallbackBefore);

        return {
            ...item,
            lmpSource: item.lmpSource || (item.isRemedial ? 'remedial' : 'custom'),
            orderKey: item.orderKey || `${createLmpOrderKey(index)}.500`,
            anchorAfterMasterEventId: fallbackAfter || undefined,
            anchorBeforeMasterEventId: fallbackBefore || undefined,
            anchorPolicy: item.anchorPolicy || 'between',
            placementNeedsReview: !(afterExists || beforeExists),
        } as SyllabusItemDetail;
    });

    const overlaysBefore = new Map<string, SyllabusItemDetail[]>();
    const overlaysAfter = new Map<string, SyllabusItemDetail[]>();
    const appendOverlays: SyllabusItemDetail[] = [];

    overlays.forEach(overlay => {
        const policy = overlay.anchorPolicy || 'between';
        const beforeId = overlay.anchorBeforeMasterEventId;
        const afterId = overlay.anchorAfterMasterEventId;

        if ((policy === 'between' || policy === 'before') && beforeId && masterIndexById.has(beforeId)) {
            const list = overlaysBefore.get(beforeId) || [];
            list.push(overlay);
            overlaysBefore.set(beforeId, list);
            return;
        }

        if (afterId && masterIndexById.has(afterId)) {
            const list = overlaysAfter.get(afterId) || [];
            list.push(overlay);
            overlaysAfter.set(afterId, list);
            return;
        }

        appendOverlays.push({ ...overlay, placementNeedsReview: true });
    });

    const result: SyllabusItemDetail[] = [];
    mergedMaster.forEach(masterItem => {
        const masterId = getMasterEventId(masterItem);
        const before = masterId ? overlaysBefore.get(masterId) || [] : [];
        result.push(...before.sort((a, b) => (a.orderKey || '').localeCompare(b.orderKey || '')));
        result.push(masterItem);
        const after = masterId ? overlaysAfter.get(masterId) || [] : [];
        result.push(...after.sort((a, b) => (a.orderKey || '').localeCompare(b.orderKey || '')));
    });

    return [...result, ...appendOverlays.sort((a, b) => (a.orderKey || '').localeCompare(b.orderKey || ''))];
};

const calculateTotalDutyHoursForPeriod = (instructorName: string, events: ScheduleEvent[], startTime: number, endTime: number, syllabusDetails: SyllabusItemDetail[]): number => {
    const instructorEvents = events.filter(e =>
        eventHasPerson(e, instructorName) &&
        // Check if event overlaps with the specified time period (considering booking windows)
        (() => {
            const bookingWindow = getEventBookingWindowForAlgo(e, syllabusDetails);
            return bookingWindow.start < endTime && bookingWindow.end > startTime;
        })()
    );

    if (instructorEvents.length === 0) return 0;

    // Calculate start/end times including pre/post brief for overlapping events
    const overlappingWindows = instructorEvents
        .map(e => getEventBookingWindowForAlgo(e, syllabusDetails))
        .map(window => ({
            start: Math.max(window.start, startTime),
            end: Math.min(window.end, endTime)
        }))
        .filter(window => window.start < window.end)
        .sort((a, b) => a.start - b.start);

    if (overlappingWindows.length === 0) return 0;

    // Merge overlapping windows to get total duty time
    let totalDutyTime = 0;
    let currentStart = overlappingWindows[0].start;
    let currentEnd = overlappingWindows[0].end;

    for (let i = 1; i < overlappingWindows.length; i++) {
        const nextWindow = overlappingWindows[i];

        if (nextWindow.start <= currentEnd) {
            // Overlapping or adjacent windows - merge them
            currentEnd = Math.max(currentEnd, nextWindow.end);
        } else {
            // Separate windows - add current window time and start new one
            totalDutyTime += currentEnd - currentStart;
            currentStart = nextWindow.start;
            currentEnd = nextWindow.end;
        }
    }

    // Add the final window
    totalDutyTime += currentEnd - currentStart;

    return parseFloat(totalDutyTime.toFixed(1));
};

const timeStringToHours = (timeStr: string | undefined): number | null => {
    if (!timeStr) return null;

    let hours: number;
    let minutes: number;

    if (timeStr.includes(':')) { // Supports HH:mm
        const parts = timeStr.split(':').map(Number);
        if (parts.length !== 2 || isNaN(parts[0]) || isNaN(parts[1])) return null;
        [hours, minutes] = parts;
    } else if (timeStr.length === 4 && /^\d{4}$/.test(timeStr)) { // Supports HHMM
        hours = parseInt(timeStr.substring(0, 2), 10);
        minutes = parseInt(timeStr.substring(2, 4), 10);
    } else {
        return null;
    }

    if (isNaN(hours) || isNaN(minutes) || hours < 0 || hours >= 24 || minutes < 0 || minutes >= 60) {
        return null;
    }
    return hours + minutes / 60;
};

const formatDecimalHourToString = (decimalHour: number): string => {
    const hours = Math.floor(decimalHour);
    const minutes = Math.round((decimalHour % 1) * 60);
    return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}`;
};

// New Helpers for DFP and Neo
const calculateProjectedDuty = (
    instructorName: string,
    events: (ScheduleEvent | Omit<ScheduleEvent, 'date'>)[],
    newEvent: (ScheduleEvent | Omit<ScheduleEvent, 'date'>),
    syllabusDetails: SyllabusItemDetail[] = []
): number => {
    // Filter events for the instructor
    const instructorEvents = [...events.filter(e => eventHasPerson(e, instructorName)), newEvent];
    if (instructorEvents.length === 0) return 0;

    // Calculate start/end times including pre/post brief
    const sortedWindows = instructorEvents
        .map(e => getEventBookingWindowForAlgo(e, syllabusDetails))
        .sort((a, b) => a.start - b.start);

    const firstEventStart = sortedWindows[0].start;

    // Determine last event end time (duty end)
    const lastEvent = instructorEvents.find(e =>
        getEventBookingWindowForAlgo(e, syllabusDetails).end === sortedWindows[sortedWindows.length - 1].end
    );

    // If the last event finishes after 1700, duty ends at event finish time.
    // Otherwise, duty assumed to end at event finish time (or could be fixed 1700 if that's business rule, but sticking to simple span here)
    const lastEventEnd = sortedWindows[sortedWindows.length - 1].end;

    const dutyHours = Math.max(0, lastEventEnd - firstEventStart);
    return parseFloat(dutyHours.toFixed(1));
};

const daysSince = (dateStr: string | undefined, relativeTo: string): number => {
    if (!dateStr) return 999; // Treated as very long ago if undefined
    const eventDate = new Date(dateStr + 'T00:00:00Z');
    const baseDate = new Date(relativeTo + 'T00:00:00Z');
    return Math.floor((baseDate.getTime() - eventDate.getTime()) / (1000 * 60 * 60 * 24));
};


// --- INSTRUCTOR PRIORITY CONFIG ---

export interface InstructorPriorityGroups {
  primary: boolean;
  secondary: boolean;
  sameFlight: boolean; // same base unit AND same flight letter (e.g. unit="CFS", flight="A")
}

export interface InstructorPriorityConfig {
  enabled: boolean;
  mode: 'soft' | 'hard';
  softGroups: InstructorPriorityGroups;  // which groups to prefer (soft mode)
  hardGroups: InstructorPriorityGroups;  // which groups MUST match for flight/FTD (hard mode)
}

export const DEFAULT_INSTRUCTOR_PRIORITY_CONFIG: InstructorPriorityConfig = {
  enabled: true,
  mode: 'soft',
  softGroups: { primary: true, secondary: true, sameFlight: false },
  hardGroups: { primary: false, secondary: false, sameFlight: false },
};

// --- DFP GENERATION ALGORITHM ---

interface DfpConfig {
  buildDate: string;
  instructors: Instructor[];
  trainees: Trainee[];
  syllabus: SyllabusItemDetail[];
  scores: Map<string, Score[]>;
  coursePriorities: string[];
  coursePercentages: Map<string, number>;
  availableAircraftCount: number;
  ftdCount: number;
  cptCount: number;
  courseColors: { [key: string]: string };
  school: string;
  dayStart: number;
  dayEnd: number;
  ftdStart: number;
  ftdEnd: number;
  allowNightFlying: boolean;
  commenceNightFlying: number;
  ceaseNightFlying: number;
  flyingWindowExclusions?: FlyingWindowExclusionPeriod[];
  highestPriorityEvents: ScheduleEvent[];
  instructorPriority: InstructorPriorityConfig;
  traineeLMPs: Map<string, SyllabusItemDetail[]>;
  flightTurnaround: number;
  ftdTurnaround: number;
  cptTurnaround: number;
  preferredDutyPeriod: number;
  maxCrewDutyPeriod: number;
  eventLimits: EventLimits;
  sctFlights: SctRequest[];
  sctFtds: SctRequest[];
  remedialRequests: RemedialRequest[];
  sctEvents: string[];
  formationCallsigns: FormationCallsign[];
  resourceDisplayNames?: ResourceDisplayNames;
  aircraftConfigurationDefinitions?: AircraftConfigurationDefinition[];
  aircraftConfigIdsByResource?: Record<string, string>;
  remedialPrioritySyncTrace?: any[];
  remedialDataMovementTrace?: any[];
  getEventDayNightClassification: (event: { flightNumber: string }, syllabusDetails: SyllabusItemDetail[], sctEvents?: string[]) => 'Day' | 'Night' | 'Day/Night';
  staffSharingEnabled: boolean;
  staffSharingUnits: string[];
  staffSharingGroups?: Array<{
    id: string;
    name: string;
    selectedUnits: string[];
    enabled?: boolean;
  }>;
  excludedCourses: string[];
  // ── DB-backed ELCE map (optional) ──────────────────────────────────────
  // Pre-fetched from /api/event-completions/elce before the build runs.
  // Maps traineeFullName → { eventCode, eventDate, dcoResult, isCountedAsElce }
  // If absent (null/undefined), computeNextEventsForTrainee falls back to the
  // legacy DFP schedule-scan ELCE.
  dbElceMap?: Map<string, { eventCode: string; eventDate: string; dcoResult: 'DCO' | 'DPCO' | 'DNCO'; isCountedAsElce: boolean } | null>;
  timingReport?: NeoBuildTimingReport;
}

// --- DFP Algorithm Helpers (moved outside for re-use in debug) ---

const isPersonStaticallyUnavailable = (
    person: Instructor | Trainee,
    periodStart: number,
    periodEnd: number,
    buildDate: string,
    eventType: 'flight' | 'ground' | 'ftd' | 'duty_sup' | 'cpt'
): boolean => {
    if (!person.unavailability) return false;
    for (const period of person.unavailability) {
        // Correct date range check: exclusive for all-day, inclusive for timed.
        const isInDateRange = period.allDay
            ? (buildDate >= period.startDate && buildDate < period.endDate)
            : (buildDate >= period.startDate && buildDate <= period.endDate);

        if (isInDateRange) {
            // Check for 'Ground Duties only' exception
            if (period.reason === 'TMUF - Ground Duties only' && eventType !== 'flight') {
                continue; // Not a conflict
            }

            if (period.allDay) {
                return true; // Conflict if it's an all-day event in range
            }

            // It's a timed event, now check for time overlap
            const unavailableStart = timeStringToHours(period.startTime);
            const unavailableEnd = timeStringToHours(period.endTime);

            if (unavailableStart !== null && unavailableEnd !== null) {
                // This logic correctly handles multi-day timed events
                let dayStart = (buildDate === period.startDate) ? unavailableStart : 0;
                let dayEnd = (buildDate === period.endDate) ? unavailableEnd : 24;

                if (periodStart < dayEnd && periodEnd > dayStart) {
                    return true; // Time overlaps
                }
            } else {
                // if times are null/invalid for a timed event, treat as all-day for that date
                return true;
            }
        }
    }
    return false; // Not unavailable
};

const findAvailableArea = (
    startTime: number,
    duration: number,
    existingEvents: Omit<ScheduleEvent, 'date'>[]
): string | null => {
    const primaryAreas = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H'];
    const secondaryAreas = ['S', 'T', 'U', 'V', 'W', 'X', 'Y', 'Z'];

    const newEventStart = startTime;
    const newEventEnd = startTime + duration;

    const isAreaOccupied = (area: string): boolean => {
        return existingEvents.some(event => {
            if (event.type !== 'flight' || event.area !== area) {
                return false;
            }
            const existingEventStart = event.startTime;
            const existingEventEnd = event.startTime + event.duration;
            return newEventStart < existingEventEnd && newEventEnd > existingEventStart;
        });
    };

    for (const primaryArea of primaryAreas) {
        if (!isAreaOccupied(primaryArea)) {
            return primaryArea;
        }
    }

    for (const secondaryArea of secondaryAreas) {
        if (!isAreaOccupied(secondaryArea)) {
            return secondaryArea;
        }
    }

    return null; // No available areas
};

/**
 * Get Effective Last Completed Event (ELCE) from yesterday's DFP
 *
 * ELCE Logic: A trainee may have flown an event yesterday that finished successfully,
 * but the paperwork (PT-051) has not been entered yet. When building tomorrow's program,
 * the scheduler looks at yesterday's DFP and treats completed events as the trainee's
 * "Effective Last Completed Event" to ensure correct Next Event determination.
 *
 * Example: Trainee flew BGF2 yesterday at 1100. PT-051 not entered yet, so system
 * shows last completed as BGF1. ELCE logic finds BGF2 in yesterday's DFP (finished,
 * not cancelled, not unsuccessful) and uses it to determine Next Event = BGF3.
 */
const getEffectiveLastCompletedEvent = (
    traineeName: string,
    publishedSchedules: Record<string, ScheduleEvent[]>,
    buildDate: string
): string | null => {
    // Calculate yesterday's date
    const buildDateObj = new Date(buildDate + 'T00:00:00Z');
    buildDateObj.setDate(buildDateObj.getDate() - 1);
    const yesterdayStr = buildDateObj.toISOString().split('T')[0];

    // Get yesterday's DFP
    const yesterdayDfp = publishedSchedules[yesterdayStr] || [];

    if (yesterdayDfp.length === 0) {
        return null;
    }

    // Find all events for this trainee from yesterday's DFP
    const traineeEvents = yesterdayDfp.filter(e =>
        e.student === traineeName || e.attendees?.includes(traineeName)
    );

    if (traineeEvents.length === 0) {
        return null;
    }

    // Filter for events that were not cancelled or marked unsuccessful
    const completedEvents = traineeEvents.filter(e => {
        const notCancelled = !e.isCancelled;
        const notUnsuccessful = !e.isUnsuccessful;
        return notCancelled && notUnsuccessful;
    });

    if (completedEvents.length === 0) {
        return null;
    }

    // Return the last completed event code (latest by start time)
    const lastEvent = completedEvents.sort((a, b) => b.startTime - a.startTime)[0];

    if (isNeoBuildVerboseDiagnosticsEnabled()) {
        console.log(`✓ ELCE for ${traineeName}: ${lastEvent.flightNumber} (completed ${yesterdayStr})`);
    }

    return lastEvent.flightNumber;
};

const normalizeLmpEventId = (value?: string | null): string => {
    return String(value || '').replace(/\*/g, '').trim();
};

const addLmpCompletionAlias = (completedEventIds: Set<string>, value?: string | null): void => {
    const raw = String(value || '').trim();
    const normalized = normalizeLmpEventId(raw);
    if (raw) completedEventIds.add(raw);
    if (normalized) completedEventIds.add(normalized);
};

const isCompletedLmpItem = (item: SyllabusItemDetail, completedEventIds: Set<string>): boolean => {
    const maybeCompleted = item as SyllabusItemDetail & { isComplete?: boolean; completed?: boolean };
    return Boolean(
        item.completedAt ||
        maybeCompleted.isComplete ||
        maybeCompleted.completed ||
        completedEventIds.has(normalizeLmpEventId(item.id)) ||
        completedEventIds.has(normalizeLmpEventId(item.code)) ||
        completedEventIds.has(normalizeLmpEventId(item.masterEventId))
    );
};

const areLmpPrerequisitesMet = (item: SyllabusItemDetail, completedEventIds: Set<string>): boolean => {
    return (item.prerequisites || []).every(prerequisite => {
        const normalized = normalizeLmpEventId(prerequisite);
        return !normalized || completedEventIds.has(normalized);
    });
};

// Centralized logic for determining a trainee's next event(s)
const computeNextEventsForTrainee = (
    trainee: Trainee,
    traineeLMPs: Map<string, SyllabusItemDetail[]>,
    scores: Map<string, Score[]>,
    masterSyllabus: SyllabusItemDetail[], // Added fallback
    publishedSchedules?: Record<string, ScheduleEvent[]>, // NEW: Optional for ELCE
    buildDate?: string, // NEW: Optional for ELCE
    dbElceMap?: Map<string, { eventCode: string; eventDate: string; dcoResult: 'DCO' | 'DPCO' | 'DNCO'; isCountedAsElce: boolean } | null> // NEW: DB-backed ELCE
): { next: SyllabusItemDetail | null, plusOne: SyllabusItemDetail | null } => {
    const verboseNeoBuild = isNeoBuildVerboseDiagnosticsEnabled();
    // Check individual LMP first, then fallback to master syllabus
    const hasIndividualLMP = traineeLMPs.has(trainee.fullName);
    const individualLMP = traineeLMPs.get(trainee.fullName) || masterSyllabus;

    // Debug logging for remedial tracking
    if (verboseNeoBuild && hasIndividualLMP) {
        const remedialEvents = individualLMP.filter(item => item.isRemedial);
        if (remedialEvents.length > 0) {
            console.log(`🔍 [${trainee.fullName}] Has Individual LMP with ${remedialEvents.length} remedial events`);
        }
    } else if (verboseNeoBuild) {
        console.log(`⚠️ [${trainee.fullName}] Using Master LMP (no Individual LMP found)`);
    }

    if (!individualLMP || individualLMP.length === 0) {
        return { next: null, plusOne: null };
    }

    const traineeScores = scores.get(trainee.fullName) || [];
    const completedEventIds = new Set<string>();
    traineeScores.forEach(score => addLmpCompletionAlias(completedEventIds, score.event));

    // The Individual LMP is now composed from the Master LMP plus overlay rows.
    // Use its completion flags directly so NEO Build does not depend on stale
    // score-map timing or legacy PT-051 tables.
    individualLMP.forEach(item => {
        const maybeCompleted = item as SyllabusItemDetail & { isComplete?: boolean; completed?: boolean };
        if (item.completedAt || maybeCompleted.isComplete || maybeCompleted.completed) {
            addLmpCompletionAlias(completedEventIds, item.id);
            addLmpCompletionAlias(completedEventIds, item.code);
            addLmpCompletionAlias(completedEventIds, item.masterEventId);
        }
    });

    // ── Source 1: DB-backed ELCE from EventCompletion table (preferred) ──────
    // This is written the moment the post-flight form is saved, before PT-051
    // paperwork is entered.  Only DCO and DPCO count; DNCO must NOT advance
    // the next-event pointer.
    const dbElce = dbElceMap?.get(trainee.fullName);
    if (dbElce && (dbElce.dcoResult === 'DCO' || dbElce.dcoResult === 'DPCO')) {
        addLmpCompletionAlias(completedEventIds, dbElce.eventCode);
        if (verboseNeoBuild) console.log(
            `[ELCE/DB] ${trainee.fullName}: ${dbElce.eventCode} (${dbElce.dcoResult}) ` +
            `completed ${dbElce.eventDate} — added to completedEventIds`
        );
    } else if (dbElce && dbElce.dcoResult === 'DNCO') {
        if (verboseNeoBuild) console.log(
            `[ELCE/DB] ${trainee.fullName}: ${dbElce.eventCode} was DNCO on ${dbElce.eventDate} ` +
            `— NOT counted as ELCE (unsuccessful sortie)`
        );
    }

    // ── Source 2: Legacy DFP schedule scan (fallback) ────────────────────────
    // Used when no DB ELCE exists yet (first day of use, or post-flight form
    // has not been submitted). Scans yesterday's published DFP for events that
    // finished but are not yet in PT-051.
    if (!dbElce && publishedSchedules && buildDate) {
        const elce = getEffectiveLastCompletedEvent(trainee.fullName, publishedSchedules, buildDate);
        if (elce) {
            addLmpCompletionAlias(completedEventIds, elce);
            if (verboseNeoBuild) console.log(`[ELCE/DFP] ${trainee.fullName}: ${elce} — DFP-scan fallback (no DB ELCE found)`);
        }
    }

    let nextEvt: SyllabusItemDetail | null = null;
    let plusOneEvt: SyllabusItemDetail | null = null;
    let nextEventIndex = -1;

    // Find Next Event
    for (let i = 0; i < individualLMP.length; i++) {
        const item = individualLMP[i];
        if (isCompletedLmpItem(item, completedEventIds) || item.code.includes(' MB')) {
            continue;
        }

        const prereqsMet = areLmpPrerequisitesMet(item, completedEventIds);
        if (prereqsMet) {
            nextEvt = item;
            nextEventIndex = i;

            // Debug logging for remedial events
            if (verboseNeoBuild && item.isRemedial) {
                console.log(`✅ [${trainee.fullName}] Next event is REMEDIAL: ${item.code}`);
            }
            break;
        }
    }

    // Find Next +1 Event (sequentially)
    if (nextEventIndex !== -1) {
        for (let i = nextEventIndex + 1; i < individualLMP.length; i++) {
            const item = individualLMP[i];
            // Skip non-schedulable events
            if (!item.code.includes(' MB') && !isCompletedLmpItem(item, completedEventIds)) {
                plusOneEvt = item;
                break;
            }
        }
    }

    return { next: nextEvt, plusOne: plusOneEvt };
};

// Helper for Trainee Priority Scoring
const calculateTraineePriorityScore = (
    trainee: Trainee,
    buildDate: string,
    courseMedian: number,
    traineeProgress: number,
    isRemedial: boolean
): number => {
    const today = new Date(buildDate + 'T00:00:00Z').getTime();
    const lastEvent = trainee.lastEventDate ? new Date(trainee.lastEventDate + 'T00:00:00Z').getTime() : 0;
    const lastFlight = trainee.lastFlightDate ? new Date(trainee.lastFlightDate + 'T00:00:00Z').getTime() : 0;

    const daysSinceEvent = lastEvent === 0 ? 100 : Math.floor((today - lastEvent) / (1000 * 3600 * 24));
    const daysSinceFlight = lastFlight === 0 ? 100 : Math.floor((today - lastFlight) / (1000 * 3600 * 24));

    // Lag is positive if they are behind the median
    const lag = courseMedian - traineeProgress;

    // Weighting Logic
    let score = 0;
    score += daysSinceEvent * 2;
    score += daysSinceFlight * 1;
    score += lag * 5; // High weight for being behind

    if (isRemedial) score += 500; // Massive boost for remedial

    return score;
};

// Planned Event Interface
interface PlannedEvent {
    id: string;
    type: 'manual' | 'sct' | 'trainee';
    subType: 'flight' | 'ftd' | 'ground' | 'cpt' | 'stby';
    priorityScore: number;
    trainee?: Trainee;
    instructor?: Instructor;
    eventCode: string;
    isRemedial: boolean;
    isSct: boolean;
}

interface CourseAnalysis {
    courseName: string;
    targetPercentage: number;
    actualPercentage: number;
    deviation: number;
    eventCount: number;
    possibleEvents: number;
    schedulingEfficiency: number;
    eventsByType: {
        flight: number;
        ftd: number;
        cpt: number;
        ground: number;
    };
    limitingFactors: {
        insufficientInstructors: number;
        noAircraftSlots: number;
        noFtdSlots: number;
        noCptSlots: number;
        traineeLimit: number;
        instructorLimit: number;
        noTimeSlots: number;
    };
    status: 'good' | 'fair' | 'poor';
}

interface TimeDistribution {
    eventsByHour: Map<number, number>;
    clusteringScore: number;
    uniformityScore: number;
}

interface ResourceUtilization {
    aircraftUtilization: number;
    instructorUtilization: number;
    ftdUtilization: number;
    standbyCount: number;
}

interface Insight {
    type: 'success' | 'warning' | 'error' | 'info';
    message: string;
    recommendation?: string;
}

interface BuildAnalysis {
    buildDate: string;
    totalEvents: number;
    availableAircraft: number;
    courseAnalysis: CourseAnalysis[];
    timeDistribution: TimeDistribution;
    resourceUtilization: ResourceUtilization;
    insights: Insight[];
}


// Helper function to count possible events per course
function countPossibleEvents(
    allTraineesData: Trainee[],
    coursePriorities: string[],
    traineeLMPs: Map<string, LMP[]>,
    scores: Map<string, Score[]>,
    syllabusDetails: SyllabusDetail[],
    publishedSchedules: Map<string, Omit<ScheduleEvent, 'date'>[]>,
    buildDate: string
): Map<string, number> {
    const possibleEventCounts = new Map<string, number>();

    // Initialize counts
    coursePriorities.forEach(course => {
        possibleEventCounts.set(course, 0);
    });

    // Count trainees with next events per course
    const activeTrainees = allTraineesData.filter(t => !t.isPaused);

    activeTrainees.forEach(trainee => {
        if (!coursePriorities.includes(trainee.course)) return;

        const { next, plusOne } = computeNextEventsForTrainee(
            trainee,
            traineeLMPs,
            scores,
            syllabusDetails,
            publishedSchedules,
            buildDate
        );

        // Count next event
        if (next) {
            const currentCount = possibleEventCounts.get(trainee.course) || 0;
            possibleEventCounts.set(trainee.course, currentCount + 1);
        }

        // Count plus-one event
        if (plusOne) {
            const currentCount = possibleEventCounts.get(trainee.course) || 0;
            possibleEventCounts.set(trainee.course, currentCount + 1);
        }
    });

    return possibleEventCounts;
}

// Analyze build results and compare to targets
function analyzeBuildResults(
    events: Omit<ScheduleEvent, 'date'>[],
    coursePercentages: Map<string, number>,
    coursePriorities: string[],
    availableAircraft: number,
    buildDate: string,
    allTraineesData: Trainee[],
    traineeLMPs: Map<string, LMP[]>,
    scores: Map<string, Score[]>,
    syllabusDetails: SyllabusDetail[],
    publishedSchedules: Map<string, Omit<ScheduleEvent, 'date'>[]>
): BuildAnalysis {
    // Filter out Duty Sup events and STBY events from analytics.
    // STBY events are not shown in build analytics until moved to the active Daily schedule.
    const scheduledEvents = events.filter(e => {
        if (e.flightNumber.includes('Duty Sup')) return false;
        if (e.resourceId.startsWith('STBY') || e.resourceId.startsWith('BNF-STBY')) return false;
        return true;
    });

    const totalEvents = scheduledEvents.length;

    // Normalize percentages
    const normalizePercentages = (percentages: Map<string, number>): Map<string, number> => {
        const total = Array.from(percentages.values()).reduce((sum, val) => sum + val, 0);
        if (total === 0) return percentages;
        const normalized = new Map<string, number>();
        percentages.forEach((value, key) => {
            normalized.set(key, (value / total) * 100);
        });
        return normalized;
    };

    const normalizedPercentages = normalizePercentages(coursePercentages);

    // Calculate actual distribution per course
    const courseEventCounts = new Map<string, number>();
    const courseEventsByType = new Map<string, { flight: number, ftd: number, cpt: number, ground: number }>();

    coursePriorities.forEach(course => {
        courseEventCounts.set(course, 0);
        courseEventsByType.set(course, { flight: 0, ftd: 0, cpt: 0, ground: 0 });
    });

    scheduledEvents.forEach(event => {
        const trainee = allTraineesData.find(t => t.fullName === event.student || t.fullName === event.pilot);
        if (trainee && coursePriorities.includes(trainee.course)) {
            const course = trainee.course;
            courseEventCounts.set(course, (courseEventCounts.get(course) || 0) + 1);

            const typeCount = courseEventsByType.get(course)!;
            if (event.type === 'flight') typeCount.flight++;
            else if (event.type === 'ftd') typeCount.ftd++;
            else if (event.type === 'cpt') typeCount.cpt++;
            else if (event.type === 'ground') typeCount.ground++;
        }
    });

    // Build course analysis
    // Count possible events per course
    const possibleEventCounts = countPossibleEvents(
        allTraineesData,
        coursePriorities,
        traineeLMPs,
        scores,
        syllabusDetails,
        publishedSchedules,
        buildDate
    );

    const courseAnalysis: CourseAnalysis[] = coursePriorities.map(course => {
        const targetPercentage = normalizedPercentages.get(course) || 0;
        const eventCount = courseEventCounts.get(course) || 0;
        const possibleEvents = possibleEventCounts.get(course) || 0;
        const actualPercentage = totalEvents > 0 ? (eventCount / totalEvents) * 100 : 0;
        const deviation = actualPercentage - targetPercentage;
        const schedulingEfficiency = possibleEvents > 0 ? (eventCount / possibleEvents) * 100 : 0;

        let status: 'good' | 'fair' | 'poor';
        if (Math.abs(deviation) <= 5) status = 'good';
        else if (Math.abs(deviation) <= 10) status = 'fair';
        else status = 'poor';

        return {
            courseName: course,
            targetPercentage,
            actualPercentage,
            deviation,
            eventCount,
            possibleEvents,
            schedulingEfficiency,
            eventsByType: courseEventsByType.get(course) || { flight: 0, ftd: 0, cpt: 0, ground: 0 },
            limitingFactors: {
                insufficientInstructors: 0,
                noAircraftSlots: 0,
                noFtdSlots: 0,
                noCptSlots: 0,
                traineeLimit: 0,
                instructorLimit: 0,
                noTimeSlots: 0
            },
            status
        };
    });

    // Calculate time distribution
    const eventsByHour = new Map<number, number>();
    for (let h = 0; h < 24; h++) {
        eventsByHour.set(h, 0);
    }

    scheduledEvents.forEach(event => {
        const hour = Math.floor(event.startTime);
        eventsByHour.set(hour, (eventsByHour.get(hour) || 0) + 1);
    });

    // Calculate clustering score (0 = perfect uniform, 1 = highly clustered)
    const avgEventsPerHour = totalEvents / 24;
    let clusteringScore = 0;
    eventsByHour.forEach(count => {
        clusteringScore += Math.abs(count - avgEventsPerHour);
    });
    clusteringScore = clusteringScore / (totalEvents * 2); // Normalize to 0-1

    // Calculate uniformity score (inverse of clustering)
    const uniformityScore = 1 - clusteringScore;

    // Calculate resource utilization
    const flightEvents = scheduledEvents.filter(e => e.type === 'flight').length;
    const ftdEvents = scheduledEvents.filter(e => e.type === 'ftd').length;
    const standbyCount = events.filter(e =>
        e.resourceId.startsWith('STBY') || e.resourceId.startsWith('BNF-STBY')
    ).length;

    const aircraftUtilization = availableAircraft > 0 ? (flightEvents / availableAircraft) * 100 : 0;

    // Generate insights
    const insights: Insight[] = [];

    // Overall status
    const allGood = courseAnalysis.every(c => c.status === 'good');
    const anyPoor = courseAnalysis.some(c => c.status === 'poor');

    if (allGood) {
        insights.push({
            type: 'success',
            message: 'Excellent! All courses achieved their target percentages within ±5%.',
            recommendation: 'Current settings are optimal. Continue monitoring future builds.'
        });
    } else if (anyPoor) {
        insights.push({
            type: 'warning',
            message: 'Some courses deviated significantly from targets (>10%).',
            recommendation: 'Review resource constraints and unavailability periods. Consider adjusting percentages or increasing resources.'
        });
    } else {
        insights.push({
            type: 'info',
            message: 'Most courses achieved their targets. Minor deviations detected.',
            recommendation: 'Monitor trends over multiple builds. Small deviations are normal with limited resources.'
        });
    }

    // Time distribution insight
    if (uniformityScore > 0.8) {
        insights.push({
            type: 'success',
            message: 'Events are well-distributed throughout the day.',
            recommendation: 'Random shuffle is working effectively to prevent clustering.'
        });
    } else if (uniformityScore < 0.6) {
        insights.push({
            type: 'warning',
            message: 'Events show some clustering in certain time periods.',
            recommendation: 'This may be due to resource constraints or unavailability. Review instructor and aircraft availability.'
        });
    }

    // Resource utilization insight
    if (aircraftUtilization > 90) {
        insights.push({
            type: 'success',
            message: `High aircraft utilization (${aircraftUtilization.toFixed(0)}%).`,
            recommendation: 'Resources are being used efficiently.'
        });
    } else if (aircraftUtilization < 60) {
        insights.push({
            type: 'info',
            message: `Aircraft utilization is ${aircraftUtilization.toFixed(0)}%.`,
            recommendation: 'Consider reducing available aircraft count or increasing trainee demand.'
        });
    }

    // Standby events insight
    if (standbyCount > 0) {
        insights.push({
            type: 'warning',
            message: `${standbyCount} events placed on standby.`,
            recommendation: 'These trainees could not be scheduled due to resource constraints. Consider increasing resources or adjusting schedules.'
        });
    }

    return {
        buildDate,
        totalEvents,
        availableAircraft,
        courseAnalysis,
        timeDistribution: {
            eventsByHour,
            clusteringScore,
            uniformityScore
        },
        resourceUtilization: {
            aircraftUtilization,
            instructorUtilization: 0, // TODO: Calculate if needed
            ftdUtilization: 0, // TODO: Calculate if needed
            standbyCount
        },
        insights
    };
}

// ═══════════════════════════════════════════════════════════════════════════
// INSTRUCTOR ALLOCATION DIAGNOSTIC SYSTEM
// Pure localStorage-based. No React state. No UI props.
// Run a build → open DevTools console → type: __downloadBuildDiagnostic()
// ═══════════════════════════════════════════════════════════════════════════

interface InstructorDiagTraineeEntry {
    traineeName: string;
    traineeUnit: string;
    eventType: string;
    syllabusCode: string;
    totalInstructorsInConfig: number;
    afterQualificationFilter: number;
    afterUnitFilter: number;
    candidatesEnteringLoop: number;
    rejections: {
        staticUnavailable: number;
        softDutyLimit: number;
        groundLimit: number;
        eventLimit: number;
        timeOverlap: number;
        crewDutyPeriod: number;
    };
    finalAvailable: number;
    instructorFound: boolean;
    zeroReason: string | null;
}

interface InstructorDiagReport {
    timestamp: string;
    buildDate: string;
    totalInstructorsInConfig: number;
    sampleInstructors: Array<{ id: string; name: string; role: string; unit: string; location: string }>;
    totalTraineesProcessed: number;
    entries: InstructorDiagTraineeEntry[];
    summary: {
        totalSchedulingAttempts: number;
        instructorFound: number;
        instructorNotFound: number;
        zeroInstructorCases: {
            noInstructorsLoaded: number;
            noQualified: number;
            noUnitMatch: number;
            allFilteredOut: number;
        };
    };
}

let _instructorDiag: InstructorDiagReport | null = null;

function _diagInitInstructors(buildDate: string, instructors: any[]) {
    if (!isNeoBuildVerboseDiagnosticsEnabled()) {
        _instructorDiag = null;
        return;
    }
    _instructorDiag = {
        timestamp: new Date().toISOString(),
        buildDate,
        totalInstructorsInConfig: instructors.length,
        sampleInstructors: instructors.slice(0, 10).map(i => ({
            id: i.idNumber || 'unknown',
            name: i.name || 'unknown',
            role: i.role || 'unknown',
            unit: i.unit || 'unknown',
            location: i.location || 'unknown',
        })),
        totalTraineesProcessed: 0,
        entries: [],
        summary: {
            totalSchedulingAttempts: 0,
            instructorFound: 0,
            instructorNotFound: 0,
            zeroInstructorCases: {
                noInstructorsLoaded: 0,
                noQualified: 0,
                noUnitMatch: 0,
                allFilteredOut: 0,
            },
        },
    };
    console.log('[INSTR-DIAG] Initialized. Instructors in config:', instructors.length);
}

function _diagRecordEntry(entry: InstructorDiagTraineeEntry) {
    if (!_instructorDiag) return;
    _instructorDiag.entries.push(entry);
    _instructorDiag.summary.totalSchedulingAttempts++;
    if (entry.instructorFound) {
        _instructorDiag.summary.instructorFound++;
    } else {
        _instructorDiag.summary.instructorNotFound++;
        if (entry.zeroReason === 'NO_INSTRUCTORS_LOADED') _instructorDiag.summary.zeroInstructorCases.noInstructorsLoaded++;
        else if (entry.zeroReason === 'NO_QUALIFIED') _instructorDiag.summary.zeroInstructorCases.noQualified++;
        else if (entry.zeroReason === 'NO_UNIT_MATCH') _instructorDiag.summary.zeroInstructorCases.noUnitMatch++;
        else if (entry.zeroReason === 'ALL_FILTERED_OUT') _instructorDiag.summary.zeroInstructorCases.allFilteredOut++;
    }
}

function _diagFinalizeInstructors() {
    if (!_instructorDiag) return;
    _instructorDiag.totalTraineesProcessed = _instructorDiag.entries.length;
    try {
        localStorage.setItem('instructor_diag_report', JSON.stringify(_instructorDiag));
        console.log('[INSTR-DIAG] ✅ Report saved to localStorage. Attempts:', _instructorDiag.summary.totalSchedulingAttempts,
            'Found:', _instructorDiag.summary.instructorFound,
            'NOT found:', _instructorDiag.summary.instructorNotFound);
        console.log('[INSTR-DIAG] Zero instructor breakdown:', JSON.stringify(_instructorDiag.summary.zeroInstructorCases));
        console.log('[INSTR-DIAG] To download: open console and type __downloadBuildDiagnostic()');
    } catch (e) {
        console.warn('[INSTR-DIAG] Failed to save to localStorage:', e);
    }
}

// Global download helper — callable from browser DevTools console
(window as any).__downloadBuildDiagnostic = () => {
    const raw = localStorage.getItem('instructor_diag_report');
    if (!raw) { console.error('No diagnostic report found. Run a build first.'); return; }
    const report = JSON.parse(raw);
    const ts = report.timestamp.replace(/[:.]/g, '-').replace('T', '_').slice(0, 19);
    const blob = new Blob([JSON.stringify(report, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `instructor-diag-${ts}.json`;
    a.click();
    URL.revokeObjectURL(url);
    console.log('[INSTR-DIAG] Download triggered:', `instructor-diag-${ts}.json`);
};

