    const [currentUserId, setCurrentUserId] = useState<number>(currentUser?.idNumber || 1);

    // Set current user for audit logging — fallback only when no auth user is set
    // (fetchAndSetAuditUser handles the primary case on login/session restore)
    useEffect(() => {
        if (!authUser && currentUser) {
            const userString = `${currentUser.rank || ''} ${currentUser.name}`.trim();
            setCurrentUser(userString);
        }
    }, [authUser, currentUser, currentUserName]);
    // Syllabus state declared here before useEffects that reference it to avoid TDZ errors
    const [syllabusDetails, setSyllabusDetails] = useState<SyllabusItemDetail[]>([]);
    const [syllabusLoading, setSyllabusLoading] = useState<boolean>(false);
    const [syllabusError, setSyllabusError] = useState<string | null>(null);

// Load syllabus from DB on mount — DB only, no mock data fallback
    useEffect(() => {
        const loadSyllabus = async () => {
            setSyllabusLoading(true);
            setSyllabusError(null);
            try {
                const result = await loadSyllabusFromDB();
                if (result.syllabus.length > 0) {
                    setSyllabusDetails(result.syllabus);
                    if (result.source === 'expired-cache') {
                        console.warn('⚠️ [Syllabus] Using expired cache:', result.error);
                        setSyllabusError(result.error || null);
                    } else {
                        console.log(`✅ [Syllabus] Loaded ${result.syllabus.length} items from ${result.source}`);
                    }
                } else {
                    console.warn('⚠️ [Syllabus] No syllabus items found in DB');
                    setSyllabusDetails([]);
                    setSyllabusError(result.error || 'No syllabus items in database');
                }
            } catch (err) {
                const msg = err instanceof Error ? err.message : 'Unknown error';
                console.error('❌ [Syllabus] Failed to load syllabus:', msg);
                setSyllabusDetails([]);
                setSyllabusError(msg);
            } finally {
                setSyllabusLoading(false);
            }
        };
        loadSyllabus();
    }, []);

// Load data from API on mount — credentials:include sends session cookie automatically
    useEffect(() => {
        // One-time migration: reset mock data toggles to OFF if they were previously defaulted ON
        // This prevents mock data contaminating real staff/trainee lists after DB is populated
        try {
            const stored = localStorage.getItem('dataSourceSettings');
            if (stored) {
                const parsed = JSON.parse(stored);
                // If mock data toggles were saved as true (old default), reset them to false
                // We detect "old default" by checking if staffDb is also true (new installs have DB on, mock off)
                if (parsed.staff === true && parsed.staffDb === true && !parsed._mockDataMigrated) {
                    parsed.staff = false;
                    parsed.trainee = false;
                    parsed._mockDataMigrated = true;
                    localStorage.setItem('dataSourceSettings', JSON.stringify(parsed));
                    setDataSourceSettings(prev => ({ ...prev, staff: false, trainee: false }));
                    console.log('🔧 Migrated dataSourceSettings: mock data toggles reset to OFF');
                }
            }
        } catch (e) {
            console.warn('Could not migrate dataSourceSettings');
        }

        const loadInitialData = async () => {
            try {
                const data = await initializeData();

                setInstructorsData(data.instructors);
                setIsStaffLoaded(true);
                setTraineesData(data.trainees);
                setIsTraineeLoaded(true);
                setEvents(data.events);

                // Load courses from DB if any exist
                if (data.courses && data.courses.length > 0) {
                    console.log('🎓 Loading', data.courses.length, 'courses from DB');
                    setCourses(data.courses);
                    // Rebuild courseColors from loaded courses
                    const colors: { [key: string]: string } = {};
                    data.courses.forEach((c: any) => { if (c.name && c.color) colors[c.name] = c.color; });
                    setCourseColors(prev => ({ ...prev, ...colors }));
                    setIsCoursesLoaded(true); // FIX: was never called when courses exist in DB
                } else {
                    setIsCoursesLoaded(true);
                    console.log('🎓 No courses in DB yet - keeping existing course state');
                }

                // --- Individual LMP Sync ---
                // For each trainee, read authoritative TraineePerformance PT-051
                // records from DB, mark those events as complete in their
                // Individual LMP, then load the composed LMP back into state.
                //
                // This runs on every app load to keep LMPs in sync with PT-051 records.
                // Always run sync unconditionally — server reads TraineePerformance directly from DB.
                {
                    console.log(`[LMP Sync] Starting Individual LMP sync (unconditional — server reads TraineePerformance from DB)...`);
                    try {
                        // Build syllabusData payload — master syllabus split by lmpType
                        // The backend has no knowledge of syllabus structure, so we send it from the frontend.
                        const bpcIpcSyllabus = syllabusDetails.filter(
                            (item: any) => (!item.lmpType || item.lmpType === 'Master LMP') && item.type !== 'Academics'
                        );
                        const ficSyllabus = syllabusDetails.filter(
                            (item: any) => item.courses && item.courses.includes('FIC')
                        );
                        const syllabusData: Record<string, any[]> = {
                            'BPC+IPC': bpcIpcSyllabus,
                            'FIC': ficSyllabus,
                        };

                        const apiBase = getAppApiBase();

                        const syncRes = await fetch(`${apiBase}/trainees/lmp-sync`, {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({ syllabusData }),
                        });

                        if (syncRes.ok) {
                            const syncData = await syncRes.json();
                            console.log(`[LMP Sync] ✅ Backend sync complete:`, syncData.summary);

                            // Now load back completed event IDs from DB LMPs into scores state
                            // so computeNextEventsForTrainee knows which events are done
                            const lmpRes = await fetch(`${apiBase}/trainees/lmp-sync?includeEvents=true`);
                            if (lmpRes.ok) {
                                const lmpData = await lmpRes.json();
                                const lmps = lmpData.lmps as Array<{
                                    traineeFullName: string;
                                    lmpType: string;
                                    events?: SyllabusItemDetail[];
                                    completedEventIds: string[];
                                }>;

                                if (lmps && lmps.length > 0) {
                                    // Update both scores state and traineeLMPs state with completion status
                                    setScores(prev => {
                                        const merged = new Map(prev);
                                        lmps.forEach(lmp => {
                                            // Only update scores for trainees that have at least 1 completed event.
                                            // Skip trainees with 0 completedEventIds to preserve mock/simulated scores
                                            // for trainees who don't yet have DB-persisted completion data.
                                            if (!lmp.completedEventIds || lmp.completedEventIds.length === 0) return;

                                            // Normalize event IDs — strip asterisks so 'BIF FTD1*' matches 'BIF FTD1'
                                            // in the syllabus (createSyllabusItem already strips asterisks from item.id)
                                            const normalizedIds = lmp.completedEventIds.map((id: string) => id.replace('*', ''));

                                            // Add LMP completions only when there is no real score record.
                                            // Do not replace actual PT-051 grades such as Fail/Marginal.
                                            const existingScores = merged.get(lmp.traineeFullName) || [];
                                            const existingEventIds = new Set(existingScores.map(score => score.event));
                                            const completionOnlyRecords: Score[] = normalizedIds
                                                .filter((eventId: string) => !existingEventIds.has(eventId))
                                                .map((eventId: string) => ({
                                                    event: eventId,
                                                    score: 3 as 0 | 1 | 2 | 3 | 4 | 5,
                                                    date: '',
                                                    instructor: '',
                                                    notes: 'LMP completion',
                                                    details: [],
                                                }));
                                            if (completionOnlyRecords.length > 0) {
                                                merged.set(lmp.traineeFullName, [...existingScores, ...completionOnlyRecords]);
                                            }
                                            console.log(`[LMP Sync] ${lmp.traineeFullName}: ${lmp.completedEventIds.length} events complete in Individual LMP`);
                                        });
                                        console.log(`[LMP Sync] ✅ ${lmps.length} trainee Individual LMPs loaded into scores state`);
                                        return merged;
                                    });

                                    // Update traineeLMPs state with completion status from database
                                    setTraineeLMPs(prev => {
                                        const newLMPs = new Map(prev);
                                        lmps.forEach(lmp => {
                                            const existingLMP = newLMPs.get(lmp.traineeFullName);
                                            if (!existingLMP && (!lmp.events || lmp.events.length === 0)) return;

                                            // Normalize event IDs - strip asterisks
                                            const normalizedCompletedIds = lmp.completedEventIds.map((id: string) => id.replace('*', ''));

                                            // Update completedAt field for each event in the Individual LMP
                                            const lmpSource = lmp.events && lmp.events.length > 0 ? lmp.events : existingLMP;
                                            const updatedLMP = lmpSource.map(item => {
                                                const itemCompletionKeys = [item.id, item.code, item.masterEventId]
                                                    .map((key: string | undefined) => (key || '').replace(/\*/g, ''))
                                                    .filter(Boolean);
                                                const isCompleted = itemCompletionKeys.some((key: string) => normalizedCompletedIds.includes(key));
                                                return {
                                                    ...item,
                                                    completedAt: isCompleted ? (item.completedAt || new Date().toISOString()) : null,
                                                    isComplete: isCompleted,
                                                    completed: isCompleted,
                                                };
                                            });

                                            newLMPs.set(lmp.traineeFullName, updatedLMP);
                                            console.log(`[LMP Sync] Updated Individual LMP for ${lmp.traineeFullName} with ${lmp.completedEventIds.length} completed events`);
                                        });
                                        console.log(`[LMP Sync] ✅ ${lmps.length} trainee Individual LMPs updated with completion status`);
                                        return newLMPs;
                                    });
                                }
                            }
                        } else {
                            console.warn('[LMP Sync] Backend sync failed, falling back to direct DB scores...');
                            // Fallback: directly apply DB PT-051 scores to state
                            // Apply BIF FTD dependency rules so BIF FTD1/BIF FTD3 show as complete
                            setScores(prev => {
                                const merged = new Map(prev);
                                Object.entries(data.scores).forEach(([traineeName, traineeScores]) => {
                                    const ts = traineeScores as Score[];
                                    const eventIds = ts.map(s => (s.event || '').replace('*', ''));
                                    const extra: Score[] = [];
                                    // BIF FTD dependency: BIF FTD2 done → add BIF FTD1
                                    if (eventIds.includes('BIF FTD2') && !eventIds.includes('BIF FTD1')) {
                                        extra.push({ event: 'BIF FTD1', score: 3, date: '', instructor: '', notes: '', details: [] });
                                    }
                                    // BIF FTD dependency: BIF1 done → add BIF FTD3
                                    if (eventIds.includes('BIF1') && !eventIds.includes('BIF FTD3')) {
                                        extra.push({ event: 'BIF FTD3', score: 3, date: '', instructor: '', notes: '', details: [] });
                                    }
                                    merged.set(traineeName, [...ts, ...extra]);
                                });
                                return merged;
                            });
                        }
                    } catch (syncErr) {
                        console.warn('[LMP Sync] Sync error, falling back to direct DB scores:', syncErr);
                        // Fallback: directly apply DB PT-051 scores to state
                        // Apply BIF FTD dependency rules so BIF FTD1/BIF FTD3 show as complete
                        setScores(prev => {
                            const merged = new Map(prev);
                            Object.entries(data.scores).forEach(([traineeName, traineeScores]) => {
                                const ts = traineeScores as Score[];
                                const eventIds = ts.map(s => (s.event || '').replace('*', ''));
                                const extra: Score[] = [];
                                // BIF FTD dependency: BIF FTD2 done → add BIF FTD1
                                if (eventIds.includes('BIF FTD2') && !eventIds.includes('BIF FTD1')) {
                                    extra.push({ event: 'BIF FTD1', score: 3, date: '', instructor: '', notes: '', details: [] });
                                }
                                // BIF FTD dependency: BIF1 done → add BIF FTD3
                                if (eventIds.includes('BIF1') && !eventIds.includes('BIF FTD3')) {
                                    extra.push({ event: 'BIF FTD3', score: 3, date: '', instructor: '', notes: '', details: [] });
                                }
                                merged.set(traineeName, [...ts, ...extra]);
                            });
                            return merged;
                        });
                    }
                }

                // Initialize Individual LMPs for all DB trainees on load
                // This ensures FIC210/FIC211 trainees get the FIC syllabus, not BPC+IPC
                const dbTrainees = data.trainees.filter((t: any) => t._dataSource === 'database');
                if (dbTrainees.length > 0) {
                    setTraineeLMPs(prev => {
                        const newLMPs = new Map(prev);
                        dbTrainees.forEach((trainee: any) => {
                            // Derive lmpType: trainee.lmpType > course.lmpType > course-name heuristic > fallback BPC+IPC
                            let lmpType = trainee.lmpType || '';
                            if (!lmpType || lmpType === 'BPC+IPC') {
                                // Check if the course definition has an explicit lmpType set
                                const courseObj = data.courses?.find((c: any) => c.name === trainee.course);
                                if (courseObj?.lmpType && courseObj.lmpType !== 'BPC+IPC') {
                                    lmpType = courseObj.lmpType;
                                    console.log(`[LMP Init] Using course lmpType "${lmpType}" for ${trainee.fullName} (${trainee.course})`);
                                }
                            }
                            if (!lmpType || lmpType === 'BPC+IPC') {
                                // Fallback: derive from course name (FIC heuristic)
                                if (trainee.course) {
                                    const courseUpper = (trainee.course as string).toUpperCase();
                                    if (courseUpper.startsWith('FIC')) {
                                        lmpType = 'FIC';
                                        console.log(`[LMP Init] Detected FIC course for ${trainee.fullName} (${trainee.course}) — overriding lmpType to 'FIC'`);
                                    }
                                }
                            }
                            if (!lmpType) lmpType = 'BPC+IPC';

                            // For FIC trainees: always assign correct FIC LMP (overwrite any incorrect BPC+IPC LMP)
                            // For non-FIC trainees: only initialize if not already set
                            const isFicTrainee = lmpType === 'FIC';
                            const alreadySet = newLMPs.has(trainee.fullName);

                            if (!alreadySet || isFicTrainee) {
                                const masterLMP = syllabusDetails.filter(item => {
                                    if (lmpType === 'BPC+IPC') {
                                        return (!item.lmpType || item.lmpType === 'Master LMP') && item.type !== 'Academics';
                                    }
                                    return item.courses && item.courses.includes(lmpType);
                                });
                                if (masterLMP.length > 0) {
                                    newLMPs.set(trainee.fullName, mergeIndividualLmpWithMaster(newLMPs.get(trainee.fullName), masterLMP));
                                    console.log(`[LMP Init] ${trainee.fullName} (${trainee.course}) → ${lmpType} LMP (${masterLMP.length} events)${isFicTrainee && alreadySet ? ' [CORRECTED]' : ''}`);
                                }
                            }
                        });
                        return newLMPs;
                    });
                }

                // Fix lmpType in DB for FIC trainees that still have the default 'BPC+IPC'
                // This is a one-time correction that runs on every load (idempotent - no-ops if already correct)
                const ficDbTrainees = data.trainees.filter((t: any) =>
                    t._dataSource === 'database' &&
                    t.course && (t.course as string).toUpperCase().startsWith('FIC') &&
                    (!t.lmpType || t.lmpType === 'BPC+IPC')
                );
                if (ficDbTrainees.length > 0) {
                    console.log(`[LMP Fix] Fixing lmpType for ${ficDbTrainees.length} FIC trainees in DB...`);
                    fetch('/api/trainees/fix-lmp-type', { method: 'PATCH' })
                        .then(r => r.json())
                        .then(result => {
                            if (result.success) {
                                console.log(`[LMP Fix] ✅ Updated ${result.count} FIC trainees' lmpType to 'FIC' in DB`);
                            }
                        })
                        .catch(err => console.warn('[LMP Fix] Could not fix lmpType:', err));
                }

                // Register any DB trainee courses that aren't in courseColors yet
                // Without this, DB-only mode shows zero trainees because CourseRosterView
                // only renders courses that exist in courseColors
                const defaultColors = [
                    'bg-sky-400/80', 'bg-purple-400/80', 'bg-yellow-400/80', 'bg-pink-400/80',
                    'bg-orange-400/80', 'bg-teal-400/80', 'bg-indigo-400/80', 'bg-green-400/80',
                    'bg-red-400/80', 'bg-cyan-400/80'
                ];
                const dbTraineesFromLoad = data.trainees.filter((t: any) => t._dataSource === 'database');
                const dbCourseNamesFromLoad = [...new Set(dbTraineesFromLoad.map((t: any) => t.course).filter(Boolean))] as string[];
                if (dbCourseNamesFromLoad.length > 0) {
                    setCourseColors(prev => {
                        const updated = { ...prev };
                        let colorIndex = Object.keys(updated).length;
                        dbCourseNamesFromLoad.forEach((course: string) => {
                            if (!updated[course]) {
                                updated[course] = defaultColors[colorIndex % defaultColors.length];
                                colorIndex++;
                                console.log(`[Initial Load] Added missing courseColor for "${course}"`);
                            }
                        });
                        return updated;
                    });
                }

                console.log('✅ State updated successfully');
            } catch (error) {
                console.error('❌ Failed to load initial data:', error);
            }
        };
        loadInitialData();
    }, []);

    // Re-initialize traineeLMPs whenever syllabusDetails loads (fixes race condition where
    // loadInitialData runs before syllabusDetails is populated, leaving all LMPs empty)
    useEffect(() => {
        if (!syllabusDetails.length || !allTraineesData.length) return;
        console.log(`[LMP Re-init] syllabusDetails loaded (${syllabusDetails.length} items), re-initializing traineeLMPs for ${allTraineesData.length} trainees`);
        setTraineeLMPs(prev => {
            const newLMPs = new Map(prev);
            allTraineesData.forEach((trainee: any) => {
                // Derive lmpType
                let lmpType = trainee.lmpType || 'BPC+IPC';
                if (lmpType === 'BPC+IPC' && trainee.course) {
                    const courseUpper = (trainee.course as string).toUpperCase();
                    if (courseUpper.startsWith('FIC')) {
                        lmpType = 'FIC';
                    }
                }
                const isFicTrainee = lmpType === 'FIC';
                const alreadySet = newLMPs.has(trainee.fullName);
                // Always set for FIC trainees; set for others only if not yet initialized
                if (!alreadySet || isFicTrainee) {
                    const masterLMP = syllabusDetails.filter(item => {
                        if (lmpType === 'BPC+IPC') {
                            return (!item.lmpType || item.lmpType === 'Master LMP') && item.type !== 'Academics';
                        }
                        return item.courses && item.courses.includes(lmpType);
                    });
                    if (masterLMP.length > 0) {
                        newLMPs.set(trainee.fullName, mergeIndividualLmpWithMaster(newLMPs.get(trainee.fullName), masterLMP));
                        console.log(`[LMP Re-init] ${trainee.fullName} (${trainee.course}) => ${lmpType} LMP (${masterLMP.length} events)`);
                    } else {
                        // Fallback: use entire syllabus if no specific match
                        newLMPs.set(trainee.fullName, mergeIndividualLmpWithMaster(newLMPs.get(trainee.fullName), syllabusDetails));
                        console.log(`[LMP Re-init] ${trainee.fullName} (${trainee.course}) => fallback to full syllabus (${syllabusDetails.length} events)`);
                    }
                }
            });
            console.log(`[LMP Re-init] Done. ${newLMPs.size} LMPs set.`);
            return newLMPs;
        });
    }, [syllabusDetails, allTraineesData]);

    // Load persisted daily snapshots (last 5 days) + legacy historical data from DB
    useEffect(() => {
        let cancelled = false;
        const requestedSchool = school;
        const requestedUnit = activeUnitCode;
        const loadHistoricalData = async () => {
            try {
                const apiBase = getAppApiBase();
                pushDfpDataDiag('history:load-start', {
                    requestedSchool,
                    requestedUnit,
                    apiBase,
                    platformDataScopeQuery,
                    existingPublishedDates: Object.keys(publishedSchedulesRef.current || {}),
                });

                // ── PRIMARY: Load last 5 days of real DailySnapshots ──────────────
                try {
                    const dailySnapshotUrl = `${apiBase}/daily-snapshot?school=${requestedSchool}&unit=${encodeURIComponent(requestedUnit)}`;
                    const snapRes = await fetch(dailySnapshotUrl);
                    if (cancelled) return;
                    pushDfpDataDiag('history:daily-snapshot-response', {
                        url: dailySnapshotUrl,
                        status: snapRes.status,
                        ok: snapRes.ok,
                    });
                    if (snapRes.ok) {
                        const snapData = await snapRes.json();
                        if (cancelled) return;
                        const snapshots: any[] = snapData.snapshots || [];
                        pushDfpDataDiag('history:daily-snapshot-json', {
                            snapshotCount: snapshots.length,
                            snapshots: snapshots.slice(0, 20).map((snap) => ({
                                key: snap.date,
                                parsedDate: getDailySnapshotDate(snap.date),
                                eventCount: Array.isArray(snap.scheduleEvents) ? snap.scheduleEvents.length : 0,
                                baselineCount: Array.isArray(snap.baselineEvents) ? snap.baselineEvents.length : 0,
                                snapshotSchool: snap.snapshotSchool,
                                snapshotUnit: snap.snapshotUnit,
                            })),
                        });
                        if (snapshots.length > 0) {
                            console.log(`[Snapshot] ✅ Loaded ${snapshots.length} daily snapshots`);
                            setPublishedSchedules(prev => {
                                if (cancelled) return prev;
                                const merged = { ...prev };
                                snapshots.forEach(snap => {
                                    const dateKey = getDailySnapshotDate(snap.date);
                                    const events: ScheduleEvent[] = Array.isArray(snap.scheduleEvents) ? snap.scheduleEvents : [];
                                    // Only use snapshot events if there are no existing non-seed events for this date
                                    const existingNonSeed = (merged[dateKey] || []).filter(e => !(e as any).isHistoricalSeed);
                                    if (existingNonSeed.length === 0 && events.length > 0) {
                                        merged[dateKey] = events;
                                    }
                                });
                                return merged;
                            });

                            // Restore baselineSchedules from snapshots (enables change bar after page reload)
                            setBaselineSchedules(prev => {
                                if (cancelled) return prev;
                                const merged = { ...prev };
                                snapshots.forEach(snap => {
                                    const dateKey = getDailySnapshotDate(snap.date);
                                    const baselineKey = `${requestedSchool}:${dateKey}`;
                                    // Use stored baselineEvents if available, otherwise fall back to scheduleEvents
                                    const baselineEvts: ScheduleEvent[] = Array.isArray(snap.baselineEvents) && snap.baselineEvents.length > 0
                                        ? snap.baselineEvents
                                        : (Array.isArray(snap.scheduleEvents) ? snap.scheduleEvents : []);
                                    if (baselineEvts.length > 0 && !merged[baselineKey]) {
                                        merged[baselineKey] = JSON.parse(JSON.stringify(baselineEvts));
                                    }
                                });
                                return merged;
                            });

                            // PT-051 active state is loaded from TraineePerformance only.
                            // Snapshot payloads may exist from older builds, but they are stale
                            // backups and must not seed or override live PT-051 results.
                            const mostRecent = snapshots[0];
                            if (mostRecent && mostRecent.pt051Assessments && Object.keys(mostRecent.pt051Assessments).length > 0) {
                                console.log(`[Snapshot] Ignored ${Object.keys(mostRecent.pt051Assessments).length} PT-051 snapshot records; TraineePerformance is authoritative`);
                            }
                            // Load alertsData from all snapshots
                            setAlertsDataByDate(prev => {
                                if (cancelled) return prev;
                                const merged = { ...prev };
                                snapshots.forEach(snap => {
                                    if (snap.alertsData && Object.keys(snap.alertsData).length > 0) {
                                        merged[getDailySnapshotDate(snap.date)] = snap.alertsData;
                                    }
                                });
                                return merged;
                            });
                        }
                    }
                } catch (snapErr) {
                    console.warn('[Snapshot] Could not load daily snapshots:', snapErr);
                }

                // ── SECONDARY: Legacy DataBackup historical-data (seed data, fallback) ──
                const historicalUrl = `${apiBase}/historical-data`;
                const res = await fetch(historicalUrl);
                if (cancelled) return;
                pushDfpDataDiag('history:legacy-response', {
                    url: historicalUrl,
                    status: res.status,
                    ok: res.ok,
                });
                if (!res.ok) return;
                const data = await res.json();
                if (cancelled) return;

                if (data.publishedSchedules && Object.keys(data.publishedSchedules).length > 0) {
                    const seedSchedules = data.publishedSchedules as Record<string, ScheduleEvent[]>;
                    const eventCount = Object.values(seedSchedules).flat().length;
                    pushDfpDataDiag('history:legacy-json', {
                        dateCount: Object.keys(seedSchedules).length,
                        eventCount,
                        dates: Object.entries(seedSchedules).slice(0, 60).map(([dateKey, seedEvents]) => ({
                            date: dateKey,
                            eventCount: Array.isArray(seedEvents) ? seedEvents.length : 0,
                        })),
                        seedingMetadata: data.seedingMetadata || null,
                    });
                    console.log(`[Historical] ✅ Loaded ${eventCount} events across ${Object.keys(seedSchedules).length} dates (legacy/seed)`);
                    setSnapshotDates(prev => (
                        [...new Set([...prev, ...Object.keys(seedSchedules)])]
                            .sort((a, b) => b.localeCompare(a))
                    ));
                    setPublishedSchedules(prev => {
                        if (cancelled) return prev;
                        // FIX: Use prev as the base (not seed schedules) so real snapshots already
                        // loaded in the PRIMARY pass above are never overwritten by seed data.
                        // Seed data fills in dates that have NO real snapshot events yet.
                        const merged = { ...prev };
                        Object.entries(seedSchedules).forEach(([dateKey, seedEvents]) => {
                            const existingNonSeed = (merged[dateKey] || []).filter(e => !(e as any).isHistoricalSeed);
                            if (existingNonSeed.length === 0) {
                                // No real snapshot for this date — use seed data
                                merged[dateKey] = seedEvents;
                            }
                            // If real snapshot data already exists for this date, do NOT overwrite it
                        });
                        return merged;
                    });
                }

                if (data.pt051Assessments && Object.keys(data.pt051Assessments).length > 0) {
                    console.log(`[Historical] Ignored ${Object.keys(data.pt051Assessments).length} legacy PT-051 records; TraineePerformance is authoritative`);
                }

                try {
                    if (!cancelled) setPt051PerformanceLoading(true);
                    const persistedAssessments: Pt051Assessment[] = [];
                    const pageSize = 2000;
                    let offset = 0;

                    while (!cancelled) {
                        const perfRes = await fetch(`${apiBase}/trainee-performance?limit=${pageSize}&offset=${offset}`);
                        if (!perfRes.ok) {
                            console.warn('[PT051] Could not load persisted trainee performance records:', await perfRes.text());
                            break;
                        }

                        const page = await perfRes.json();
                        if (!Array.isArray(page) || page.length === 0) break;

                        persistedAssessments.push(...page);
                        if (page.length < pageSize) break;
                        offset += pageSize;
                    }

                    if (!cancelled && persistedAssessments.length > 0) {
                        console.log(`[PT051] ✅ Loaded ${persistedAssessments.length} persisted trainee performance records`);
                        setPt051Assessments(prev => {
                            if (cancelled) return prev;
                            const merged = new Map(prev);
                            persistedAssessments.forEach((assessment: Pt051Assessment) => {
                                if (!assessment?.eventId || !assessment?.traineeFullName) return;
                                merged.set(`pt051-${assessment.eventId}-${assessment.traineeFullName}`, assessment);
                            });
                            return merged;
                        });
                    }
                } catch (perfErr) {
                    console.warn('[PT051] Could not load persisted trainee performance records:', perfErr);
                } finally {
                    if (!cancelled) setPt051PerformanceLoading(false);
                }

                if (data.seedingMetadata) {
                    console.log(`[Historical] Seeded at: ${data.seedingMetadata.seededAt}, courses: ${(data.seedingMetadata.coursesSeeded || []).join(', ')}`);
                }
            } catch (error) {
                console.warn('[Historical] Could not load historical data:', error);
                if (!cancelled) setPt051PerformanceLoading(false);
            }
        };
        loadHistoricalData();
        return () => {
            cancelled = true;
        };
    }, [activeUnitCode, school]);

    // Load snapshot dates for calendar dropdown
    useEffect(() => {
        const loadSnapshotDates = async () => {
            try {
                const apiBase = getAppApiBase();
                const snapshotDatesUrl = `${apiBase}/daily-snapshot/dates`;
                const res = await fetch(snapshotDatesUrl);
                pushDfpDataDiag('snapshot-dates:response', {
                    url: snapshotDatesUrl,
                    status: res.status,
                    ok: res.ok,
                });
                if (!res.ok) return;
                const data = await res.json();
                const dates: string[] = [...new Set((data.dates || []).map((d: any) => d.date))] as string[];
                pushDfpDataDiag('snapshot-dates:json', {
                    count: dates.length,
                    dates: dates.slice(0, 80),
                    rawRows: (data.dates || []).slice(0, 30),
                });
                console.log(`[Snapshot] ✅ Loaded ${dates.length} snapshot dates for calendar`);
                setSnapshotDates(prev => (
                    [...new Set([...prev, ...dates])]
                        .sort((a, b) => b.localeCompare(a))
                ));
            } catch (err) {
                console.warn('[Snapshot] Could not load snapshot dates:', err);
            }
        };
        loadSnapshotDates();
    }, []);

    const applyDailySnapshot = React.useCallback((
        targetDate: string,
        snapshotSchool: string,
        snapshotUnit: string,
        snap: any,
        replace: boolean,
        source: 'cache' | 'network'
    ): number => {
        if (!snap) return 0;

        const events: ScheduleEvent[] = Array.isArray(snap.scheduleEvents) ? snap.scheduleEvents : [];
        pushDfpDataDiag('snapshot:apply', {
            targetDate,
            snapshotSchool,
            snapshotUnit,
            source,
            replace,
            eventCount: events.length,
            existingCount: (publishedSchedulesRef.current[targetDate] || []).length,
            snapKey: snap.date,
            sampleEvents: events.slice(0, 8).map((event) => ({
                id: event.id,
                date: event.date,
                type: event.type,
                resourceId: event.resourceId,
                startTime: event.startTime,
                flightNumber: event.flightNumber,
                instructor: event.instructor,
                student: event.student,
            })),
        });
        if (events.length > 0) {
            setPublishedSchedules(prev => {
                const existingNonSeed = (prev[targetDate] || []).filter(e => !(e as any).isHistoricalSeed);
                if (!replace && existingNonSeed.length > 0) return prev;
                return { ...prev, [targetDate]: events };
            });

            const baselineEvts: ScheduleEvent[] = Array.isArray(snap.baselineEvents) && snap.baselineEvents.length > 0
                ? snap.baselineEvents
                : events;
            setBaselineSchedules(prev => {
                const baselineKey = getDailySnapshotKey(targetDate, snapshotSchool, snapshotUnit);
                if (!replace && prev[baselineKey]) return prev;
                return { ...prev, [baselineKey]: JSON.parse(JSON.stringify(baselineEvts)) };
            });
            console.log(`[Snapshot] ✅ Loaded ${source} snapshot for ${targetDate} (${snapshotSchool} - ${snapshotUnit || 'unit not set'}), ${events.length} events`);
        }

        if (snap.pt051Assessments && Object.keys(snap.pt051Assessments).length > 0) {
            console.log(`[Snapshot] Ignored ${Object.keys(snap.pt051Assessments).length} PT-051 snapshot records for ${targetDate}; TraineePerformance is authoritative`);
        }

        if (snap.alertsData && Object.keys(snap.alertsData).length > 0) {
            setAlertsDataByDate(prev => ({ ...prev, [targetDate]: snap.alertsData }));
        }

        if (snap.aircraftConfigState && Object.keys(snap.aircraftConfigState).length > 0) {
            const baselineKey = getDailySnapshotKey(targetDate, snapshotSchool, snapshotUnit);
            setAircraftConfigStateByDate(prev => ({
                ...prev,
                [baselineKey]: snap.aircraftConfigState,
            }));
        }

        return events.length;
    }, [activeUnitCode]);

    const getDailySnapshotLocationAliases = React.useCallback((locationCode: string): string[] => {
        const normalisedLocationCode = String(locationCode || '').trim().toUpperCase();
        const matchingLocation = (platformConfig?.locations || [])
            .filter((location: any) => location.status !== 'INACTIVE')
            .find((location: any) => getLocationSelectorAliases(location).includes(normalisedLocationCode));
        return [
            normalisedLocationCode,
            ...knownDfpLocationAliases(normalisedLocationCode),
            ...(matchingLocation ? getLocationSelectorAliases(matchingLocation) : []),
        ].map(alias => String(alias || '').trim().toUpperCase()).filter((alias, index, aliases) => (
            Boolean(alias) && aliases.indexOf(alias) === index
        ));
    }, [getLocationSelectorAliases, knownDfpLocationAliases, platformConfig]);

    // Load a single day snapshot on demand (when user navigates to a date not yet loaded)
    const loadSnapshotForDate = React.useCallback(async (
        targetDate: string,
        options: { force?: boolean; replace?: boolean; schoolOverride?: string; unitOverride?: string; useCache?: boolean } = {}
    ) => {
        const { force = false, replace = false, schoolOverride, unitOverride, useCache = true } = options;
        const snapshotSchool = schoolOverride ?? school;
        const snapshotUnit = unitOverride ?? activeUnitCode;
        const snapshotKey = getDailySnapshotKey(targetDate, snapshotSchool, snapshotUnit);
        const snapshotLocationAliases = getDailySnapshotLocationAliases(snapshotSchool);
        const cacheKey = `dfp_snapshot_cache_${snapshotKey}`;
        pushDfpDataDiag('snapshot:load-start', {
            targetDate,
            snapshotSchool,
            snapshotUnit,
            snapshotKey,
            snapshotLocationAliases,
            cacheKey,
            force,
            replace,
            useCache,
            loaded: loadedSnapshotDates.current.has(snapshotKey),
            loading: loadingSnapshotDates.current.has(snapshotKey),
            existingEventsForTarget: (publishedSchedulesRef.current[targetDate] || []).length,
        });

        if (!force && loadedSnapshotDates.current.has(snapshotKey)) {
            pushDfpDataDiag('snapshot:load-skip-loaded', { targetDate, snapshotKey });
            return;
        }
        if (loadingSnapshotDates.current.has(snapshotKey)) {
            pushDfpDataDiag('snapshot:load-skip-loading', { targetDate, snapshotKey });
            return;
        }
        loadingSnapshotDates.current.add(snapshotKey);

        let cachedEventsSignature: string | null = null;
        if (useCache && !replace) {
            try {
                const cachedSnapshot = localStorage.getItem(cacheKey);
                pushDfpDataDiag('snapshot:cache-check', {
                    targetDate,
                    snapshotKey,
                    cacheKey,
                    hit: Boolean(cachedSnapshot),
                    byteLength: cachedSnapshot?.length || 0,
                });
                if (cachedSnapshot) {
                    const parsedCachedSnapshot = JSON.parse(cachedSnapshot);
                    const cachedEvents = applyDailySnapshot(targetDate, snapshotSchool, snapshotUnit, parsedCachedSnapshot, false, 'cache');
                    if (cachedEvents > 0) {
                        cachedEventsSignature = getSnapshotEventsSignature(parsedCachedSnapshot.scheduleEvents || []);
                        setDfpSnapshotLoadState({
                            status: 'cached',
                            date: targetDate,
                            message: 'Showing cached DFP while refreshing',
                            progress: 45
                        });
                    }
                }
            } catch (err) {
                console.warn(`[Snapshot] Could not read cached snapshot for ${targetDate}:`, err);
            }
        }

        const retryDelays = [0, 2000, 5000, 10000];

        try {
            const apiBase = getAppApiBase();
            let lastError: unknown = null;

            for (let attempt = 0; attempt < retryDelays.length; attempt++) {
                const delay = retryDelays[attempt];
                if (delay > 0) {
                    setDfpSnapshotLoadState({
                        status: 'retrying',
                        date: targetDate,
                        message: `Retrying DFP load (${attempt + 1}/${retryDelays.length})`,
                        progress: Math.min(70, 18 + attempt * 12)
                    });
                    await new Promise(resolve => setTimeout(resolve, delay));
                } else {
                    setDfpSnapshotLoadState({
                        status: 'loading',
                        date: targetDate,
                        message: 'Loading DFP',
                        progress: 10
                    });
                }

                try {
                    const candidateKeys = [
                        ...snapshotLocationAliases.map(locationAlias => getDailySnapshotKey(targetDate, locationAlias, snapshotUnit)),
                        ...snapshotLocationAliases.map(locationAlias => getDailySnapshotKey(targetDate, locationAlias, '')),
                        targetDate,
                    ].filter((key, index, keys) => Boolean(key) && keys.indexOf(key) === index);

                    let res: Response | null = null;
                    let resolvedSnapshotKey = snapshotKey;
                    for (const [candidateIndex, candidateKey] of candidateKeys.entries()) {
                        const progress = Math.min(82, 18 + Math.round((candidateIndex / Math.max(candidateKeys.length, 1)) * 56));
                        setDfpSnapshotLoadState({
                            status: attempt > 0 ? 'retrying' : 'loading',
                            date: targetDate,
                            message: `Retrieving DFP data (${candidateIndex + 1}/${candidateKeys.length})`,
                            progress
                        });
                        const candidateUrl = `${apiBase}/daily-snapshot/${encodeURIComponent(candidateKey)}`;
                        const candidateRes = await fetch(candidateUrl);
                        pushDfpDataDiag('snapshot:fetch-response', {
                            kind: candidateKey === targetDate
                                ? 'legacy-date'
                                : candidateKey.includes(`__${snapshotUnit}`)
                                    ? 'unit-scoped-or-alias'
                                    : 'location-scoped-or-alias',
                            url: candidateUrl,
                            candidateKey,
                            canonicalSnapshotKey: snapshotKey,
                            status: candidateRes.status,
                            ok: candidateRes.ok,
                        });
                        res = candidateRes;
                        resolvedSnapshotKey = candidateKey;
                        if (candidateRes.ok || candidateRes.status !== 404) {
                            break;
                        }
                    }

                    if (!res || res.status === 404) {
                        if (replace) {
                            setPublishedSchedules(prev => ({ ...prev, [targetDate]: [] }));
                            setBaselineSchedules(prev => ({ ...prev, [snapshotKey]: [] }));
                        }
                        loadedSnapshotDates.current.add(snapshotKey);
                        pushDfpDataDiag('snapshot:load-empty', {
                            targetDate,
                            snapshotKey,
                            candidateKeys,
                            replace,
                        });
                        setDfpSnapshotLoadState({
                            status: 'empty',
                            date: targetDate,
                            message: 'No published DFP for this date',
                            progress: 100
                        });
                        return;
                    }

                    if (!res.ok) {
                        lastError = new Error(`Snapshot request failed with ${res.status}`);
                        continue;
                    }

                    setDfpSnapshotLoadState({
                        status: attempt > 0 ? 'retrying' : 'loading',
                        date: targetDate,
                        message: 'Reading DFP data',
                        progress: 88
                    });
                    const data = await res.json();
                    const snap = data.snapshot;
                    pushDfpDataDiag('snapshot:network-json', {
                        targetDate,
                        snapshotKey,
                        resolvedSnapshotKey,
                        snapKey: snap?.date,
                        eventCount: Array.isArray(snap?.scheduleEvents) ? snap.scheduleEvents.length : 0,
                        baselineCount: Array.isArray(snap?.baselineEvents) ? snap.baselineEvents.length : 0,
                    });
                    if (!snap) {
                        lastError = new Error('Snapshot response did not include snapshot data');
                        continue;
                    }

                    const currentEventsSignature = getSnapshotEventsSignature(publishedSchedulesRef.current[targetDate] || []);
                    const shouldReplaceCachedEvents = !!cachedEventsSignature && currentEventsSignature === cachedEventsSignature;
                    setDfpSnapshotLoadState({
                        status: attempt > 0 ? 'retrying' : 'loading',
                        date: targetDate,
                        message: 'Applying DFP data',
                        progress: 94
                    });
                    const eventCount = applyDailySnapshot(targetDate, snapshotSchool, snapshotUnit, snap, replace || shouldReplaceCachedEvents, 'network');
                    cacheDailySnapshot(snapshotKey, snap, targetDate);
                    loadedSnapshotDates.current.add(snapshotKey);
                    setDfpSnapshotLoadState({
                        status: 'loaded',
                        date: targetDate,
                        message: eventCount > 0 ? `Loaded ${eventCount} DFP events` : 'DFP loaded',
                        progress: 100
                    });
                    return;
                } catch (err) {
                    lastError = err;
                }
            }

            throw lastError || new Error('Snapshot request failed');
        } catch (err) {
            setDfpSnapshotLoadState({
                status: 'error',
                date: targetDate,
                message: 'DFP did not load. Check connection or retry.',
                progress: 100
            });
            console.warn(`[Snapshot] Could not load snapshot for ${targetDate}:`, err);
        } finally {
            loadingSnapshotDates.current.delete(snapshotKey);
        }
    }, [activeUnitCode, applyDailySnapshot, getDailySnapshotLocationAliases, school]);

    useEffect(() => {
        if (!date || !/^\d{4}-\d{2}-\d{2}$/.test(date)) return;
        void loadSnapshotForDate(date, { useCache: true });
    }, [activeUnitCode, date, school, loadSnapshotForDate]);

