    // Currency setup state
    const [masterCurrencies, setMasterCurrencies] = useState<MasterCurrency[]>(INITIAL_MASTER_CURRENCIES);
    const [currencyRequirements, setCurrencyRequirements] = useState<CurrencyRequirement[]>(INITIAL_CURRENCY_REQUIREMENTS);
    const [showCurrencySetup, setShowCurrencySetup] = useState(false);

    // Unsaved changes state
    const [dirtyCheck, setDirtyCheck] = useState<{ isDirty: () => boolean; onSave: () => void; onDiscard: () => void } | null>(null);
    const [showUnsavedWarning, setShowUnsavedWarning] = useState(false);
    const [pendingNavigation, setPendingNavigation] = useState<string | null>(null);

    // Logbook Navigation
    const [selectedPersonForLogbook, setSelectedPersonForLogbook] = useState<Instructor | Trainee | null>(null);

    // Settings state
    const [locations, setLocations] = useState<string[]>(['East Sale', 'Pearce', 'Williamtown', 'Amberley', 'Tindal', 'Edinburgh']);
    const [locationAbbreviations, setLocationAbbreviations] = useState<Record<string, string>>({
        'East Sale': 'ESL',
        'Pearce': 'PEA',
        'Williamtown': 'WLM',
        'Amberley': 'AMB',
        'Tindal': 'TIN',
        'Edinburgh': 'EDI',
    });
    const [serviceDefinitions, setServiceDefinitions] = useState<Array<{ longName: string; shortName: string }>>([
        { longName: 'Air Force', shortName: 'RAAF' },
        { longName: 'Navy',      shortName: 'RAN'  },
        { longName: 'Army',      shortName: 'ARA'  },
    ]);
    const [locationOpAreas, setLocationOpAreas] = useState<Record<string, string[]>>({
        'East Sale': ['A','B','C','D','E','F','G','H','S','T','U','V','W','X','Y','Z'],
        'Pearce': [],
        'Williamtown': [],
    });
    const [sctEvents, setSctEvents] = useState<string[]>(['SCT GF', 'SCT IF', 'SCT FORM', 'SCT Nav', 'Night SCT']);
    const [units, setUnits] = useState<string[]>(['1FTS', 'CFS', '2FTS', '76SQN', '77SQN', '1SQN', '6SQN', '2SQN', '10SQN']);
    const [unitLocations, setUnitLocations] = useState<Record<string, string>>({
        '1FTS': 'East Sale', 'CFS': 'East Sale', '2FTS': 'Pearce', '76SQN': 'Williamtown', '77SQN': 'Williamtown',
        '1SQN': 'Amberley', '6SQN': 'Amberley', '2SQN': 'Williamtown', '10SQN': 'Edinburgh'
    });
    const [formationCallsigns, setFormationCallsigns] = useState<FormationCallsign[]>([
        { name: 'Avon', code: 'AVON', unit: '1FTS', location: 'East Sale', locationCode: 'ESL' },
        { name: 'Garret', code: 'GART', unit: '1FTS', location: 'East Sale', locationCode: 'ESL' },
        { name: 'Gypsy', code: 'GYPS', unit: '1FTS', location: 'East Sale', locationCode: 'ESL' },
        { name: 'Merlin', code: 'MERL', unit: '1FTS', location: 'East Sale', locationCode: 'ESL' },
        { name: 'Mustang', code: 'MUST', unit: 'CFS', location: 'East Sale', locationCode: 'ESL' },
        { name: 'Spitfire', code: 'SPIT', unit: 'CFS', location: 'East Sale', locationCode: 'ESL' },
        { name: 'Tempest', code: 'TMPS', unit: 'CFS', location: 'East Sale', locationCode: 'ESL' },
        { name: 'Typhoon', code: 'TYPN', unit: 'CFS', location: 'East Sale', locationCode: 'ESL' },
        { name: 'Roulettes', code: 'RLTS', unit: 'CFS', location: 'East Sale', locationCode: 'ESL' },
        { name: 'Vampire', code: 'VAMP', unit: '2FTS', location: 'Pearce', locationCode: 'PEA' },
        { name: 'Voodoo', code: 'VODO', unit: '2FTS', location: 'Pearce', locationCode: 'PEA' },
        { name: 'Vulcan', code: 'VULC', unit: '2FTS', location: 'Pearce', locationCode: 'PEA' }
    ]);


    // ─── SETTINGS: Load from DB on startup ───────────────────────────────────

    useEffect(() => {
        const loadSettings = async () => {
            try {
                const saved = await loadSettingsFromDB();
                if (!saved) {
                    setSettingsLoaded(true);
                    return;
                }

                // Apply all saved settings to state
                if (saved.locations?.length) setLocations(saved.locations);
                if (saved.locationAbbreviations && Object.keys(saved.locationAbbreviations).length) setLocationAbbreviations(saved.locationAbbreviations);
                if (saved.serviceDefinitions?.length) setServiceDefinitions(saved.serviceDefinitions);
                if (saved.units?.length) setUnits(saved.units);
                if (saved.unitLocations) setUnitLocations(saved.unitLocations);
                if (saved.locationOpAreas) setLocationOpAreas(saved.locationOpAreas);
                const savedLocations = saved.locations?.length ? saved.locations : locations;
                const savedLocationAbbreviations = {
                    ...locationAbbreviations,
                    ...(saved.locationAbbreviations || {}),
                };
                const savedUnits = saved.units?.length ? saved.units : units;
                const savedUnitLocations = saved.unitLocations || unitLocations;
                const savedLocationOpAreas = saved.locationOpAreas || locationOpAreas;
                const resolveLegacyLocationCode = (locationValue: string): string => {
                    const raw = String(locationValue || '').trim();
                    if (!raw) return '';
                    if (savedLocationAbbreviations[raw]) return String(savedLocationAbbreviations[raw]).trim();
                    const matchingLocationName = savedLocations.find((locationName) => (
                        String(locationName || '').trim().toLowerCase() === raw.toLowerCase()
                    ));
                    if (matchingLocationName && savedLocationAbbreviations[matchingLocationName]) {
                        return String(savedLocationAbbreviations[matchingLocationName]).trim();
                    }
                    return raw;
                };
                const legacyPlatformLocations = savedLocations
                    .map((locationName) => ({
                        code: resolveLegacyLocationCode(locationName),
                        iataCode: resolveLegacyLocationCode(locationName),
                        name: String(locationName || '').trim(),
                        organisationCode: 'DEFAULT',
                        timezoneOffset: 10,
                        trainingAreas: savedLocationOpAreas[locationName] || [],
                        status: 'ACTIVE',
                        settings: { source: 'legacy-settings' },
                    }))
                    .filter((location) => location.code && location.name);
                const legacyPlatformUnits = savedUnits
                    .map((unitCode) => {
                        const code = String(unitCode || '').trim();
                        const locationCode = resolveLegacyLocationCode(savedUnitLocations[code] || '');
                        return {
                            code,
                            name: code,
                            organisationCode: 'DEFAULT',
                            locationCode,
                            unitType: 'Training',
                            status: 'ACTIVE',
                            settings: {
                                source: 'legacy-settings',
                                operationalModel: normaliseOperationalModel('flight_school'),
                            },
                        };
                    })
                    .filter((unit) => unit.code && unit.locationCode);
                pushDfpDataDiag('settings:legacy-platform-merge', {
                    savedLocations,
                    savedLocationAbbreviations,
                    savedUnits,
                    savedUnitLocations,
                    legacyPlatformLocations,
                    legacyPlatformUnits,
                });
                setPlatformConfig(prev => {
                    const base = prev || {
                        organisations: [],
                        locations: [],
                        units: [],
                        aircraftTypes: [],
                        resourcePools: [],
                        modules: [],
                        unitModules: [],
                        userAccess: [],
                        platformUsers: [],
                        schedulingRuleSets: [],
                    };
                    const existingLocationCodes = new Set((base.locations || []).map((location: any) => String(location.code || '').trim().toUpperCase()));
                    const existingLocationNames = new Set((base.locations || []).map((location: any) => String(location.name || '').trim().toLowerCase()));
                    const existingUnitCodes = new Set((base.units || []).map((unit: any) => String(unit.code || '').trim().toUpperCase()));
                    return {
                        ...base,
                        locations: [
                            ...(base.locations || []),
                            ...legacyPlatformLocations.filter(location => (
                                !existingLocationCodes.has(location.code.toUpperCase())
                                && !existingLocationNames.has(location.name.toLowerCase())
                            )),
                        ],
                        units: [
                            ...(base.units || []),
                            ...legacyPlatformUnits.filter(unit => !existingUnitCodes.has(unit.code.toUpperCase())),
                        ],
                    };
                });
                if (saved.eventLimits) setEventLimits(saved.eventLimits);
                if (saved.preferredDutyPeriod != null) setPreferredDutyPeriod(saved.preferredDutyPeriod);
                if (saved.maxCrewDutyPeriod != null) setMaxCrewDutyPeriod(saved.maxCrewDutyPeriod);
                if (saved.maxDispatchPerHour != null) setMaxDispatchPerHour(saved.maxDispatchPerHour);
                if (saved.flightTurnaround != null) setFlightTurnaround(saved.flightTurnaround);
                if (saved.ftdTurnaround != null) setFtdTurnaround(saved.ftdTurnaround);
                if (saved.cptTurnaround != null) setCptTurnaround(saved.cptTurnaround);
                if (saved.flyingStartTime != null) setFlyingStartTime(saved.flyingStartTime);
                if (saved.flyingEndTime != null) setFlyingEndTime(saved.flyingEndTime);
                if (saved.ftdStartTime != null) setFtdStartTime(saved.ftdStartTime);
                if (saved.ftdEndTime != null) setFtdEndTime(saved.ftdEndTime);
                if (saved.allowNightFlying != null) setAllowNightFlying(saved.allowNightFlying);
                if (saved.commenceNightFlying != null) setCommenceNightFlying(saved.commenceNightFlying);
                if (saved.ceaseNightFlying != null) setCeaseNightFlying(saved.ceaseNightFlying);
                if (Array.isArray(saved.flyingWindowExclusions)) setFlyingWindowExclusions(saved.flyingWindowExclusions);
                // NOTE: availableAircraftCount is intentionally NOT restored from settings here.
                // It is always loaded from the AircraftAvailabilityEvent table via fetchCurrentAvailability
                // (which runs after settingsLoaded becomes true), ensuring the events-table value always wins.
                // Settings value is kept as a secondary fallback only if events table has no data.
                if (saved.availableAircraftCount != null && !availabilityLoadedFromEventsRef.current) {
                    setAvailableAircraftCount(saved.availableAircraftCount);
                }
                if (saved.neoAvailableAircraftCount != null) {
                    setNeoAvailableAircraftCount(saved.neoAvailableAircraftCount);
                } else if (saved.availableAircraftCount != null) {
                    setNeoAvailableAircraftCount(saved.availableAircraftCount);
                }
                if (saved.neoAircraftConfigCapacities) {
                    setNeoAircraftConfigCapacities(saved.neoAircraftConfigCapacities);
                }
                if (saved.availableFtdCount != null) setAvailableFtdCount(saved.availableFtdCount);
                if (saved.availableCptCount != null) setAvailableCptCount(saved.availableCptCount);
                if (saved.timezoneOffset != null) setTimezoneOffset(saved.timezoneOffset);
                if (saved.showDepartureDensityOverlay != null) setShowDepartureDensityOverlay(saved.showDepartureDensityOverlay);
                if (saved.tileStatusSettings) setTileStatusSettings(normaliseTileStatusSettings(saved.tileStatusSettings));
                if (saved.sctEvents?.length) setSctEvents(saved.sctEvents);
                if (saved.formationCallsigns?.length) setFormationCallsigns(saved.formationCallsigns);
                if (saved.courseColors && Object.keys(saved.courseColors).length) setCourseColors(saved.courseColors);
                if (saved.coursePercentages && Object.keys(saved.coursePercentages).length) {
                    setCoursePercentages(new Map(Object.entries(saved.coursePercentages).map(([k, v]) => [k, v as number])));
                }
                if (saved.coursePriorities && saved.coursePriorities.length) {
                    // Filter coursePriorities by current locality - only include courses
                    // that have trainees belonging to this school (ESL/PEA)
                    const locationFullName = school === 'ESL' ? 'East Sale' : 'Pearce';
                    const locationShortCode = school === 'ESL' ? 'ESL' : 'PEA';
                    const localityCourses = saved.coursePriorities.filter(course => {
                        const courseTrainees = allTraineesData.filter(t => t.course === course);
                        return courseTrainees.some(t => {
                            if (t.location) return t.location === locationFullName || t.location === locationShortCode || t.location === school;
                            if (t.unit) {
                                if (t.unit.startsWith('2FTS')) return locationFullName === 'Pearce';
                                if (t.unit.startsWith('1FTS') || t.unit.startsWith('CFS')) return locationFullName === 'East Sale';
                            }
                            return false;
                        });
                    });
                    setCoursePriorities(localityCourses);
                }
                if (saved.phraseBank && Object.keys(saved.phraseBank).length) setPhraseBank(saved.phraseBank);
                if (saved.cancellationCodes?.length) setCancellationCodes(saved.cancellationCodes);
                // Merge DB currencies with initial defaults — ensures new fields/currencies are always present
                {
                    const dbReqs = saved.currencyRequirements ?? [];
                    const dbMasters = saved.masterCurrencies ?? [];
                    const merged = mergeWithInitialCurrencies(dbReqs, dbMasters);
                    setMasterCurrencies(merged.masters);
                    setCurrencyRequirements(merged.requirements);
                }
                // NOTE: syllabusDetails intentionally NOT loaded from settings DB.
                // syllabusDetails is always loaded from the DB syllabus API (DB only, no mock data).
                // The loadSyllabus useEffect above handles all syllabus loading.
                if (saved.organisationSettings) {
                    console.log('[App] 🏢 Setting organisationSettings from DB:', JSON.stringify(saved.organisationSettings));
                    pushContextSelectorDiag('settings:organisation-loaded', {
                        fleetSharingEnabled: saved.organisationSettings.fleetSharingEnabled,
                        selectedUnits: saved.organisationSettings.selectedUnits,
                        resourceSharingGroups: saved.organisationSettings.resourceSharingGroups,
                    });
                    setOrganisationSettings(saved.organisationSettings);
                } else {
                    console.warn('[App] ⚠️ No organisationSettings found in DB data — saved.organisationSettings is:', saved.organisationSettings);
                    pushContextSelectorDiag('settings:organisation-missing');
                }

                console.log('[Settings] ✅ All settings restored from DB');
            } catch (error) {
                console.error('[Settings] ❌ Failed to load settings from DB:', error);
                pushContextSelectorDiag('settings:load-error', { error: String(error) });
            } finally {
                console.log('[App] 🏁 Setting settingsLoaded = true');
                pushContextSelectorDiag('settings:loaded-flag-true');
                setSettingsLoaded(true);
            }
        };
        loadSettings();
    }, []);

    // ─── SETTINGS: Auto-save when anything changes ────────────────────────────
    useEffect(() => {
        if (!settingsLoaded) {
            console.log('[App] ⏭️ Auto-save skipped — settingsLoaded is false');
            return;
        }

        console.log('[App] 💾 Auto-save triggered — organisationSettings:', JSON.stringify(organisationSettings));

        const snapshot = buildSettingsSnapshot({
            locations,
            locationAbbreviations,
            serviceDefinitions,
            units,
            unitLocations,
            locationOpAreas,
            eventLimits,
            preferredDutyPeriod,
            maxCrewDutyPeriod,
            maxDispatchPerHour,
            flightTurnaround,
            ftdTurnaround,
            cptTurnaround,
            flyingStartTime,
            flyingEndTime,
            ftdStartTime,
            ftdEndTime,
            allowNightFlying,
            commenceNightFlying,
            ceaseNightFlying,
            flyingWindowExclusions,
            availableAircraftCount,
            neoAvailableAircraftCount,
            neoAircraftConfigCapacities,
            availableFtdCount,
            availableCptCount,
            timezoneOffset,
            showDepartureDensityOverlay,
            tileStatusSettings,
            sctEvents,
            formationCallsigns,
            courseColors,
            phraseBank,
            cancellationCodes,
            masterCurrencies,
            currencyRequirements,
            // NOTE: syllabusDetails intentionally excluded from settings save.
            // Syllabus is always loaded from DB via the dedicated syllabus API,
            // never from the general settings blob.
            organisationSettings,
            coursePriorities,
            coursePercentages: Object.fromEntries(coursePercentages),
        });

        saveSettingsToDB(snapshot, sessionUser?.userId);
    }, [
        settingsLoaded,
        locations, locationAbbreviations, serviceDefinitions, units, unitLocations, locationOpAreas,
        eventLimits,
        preferredDutyPeriod, maxCrewDutyPeriod, maxDispatchPerHour,
        flightTurnaround, ftdTurnaround, cptTurnaround,
        flyingStartTime, flyingEndTime, ftdStartTime, ftdEndTime,
        allowNightFlying, commenceNightFlying, ceaseNightFlying,
        flyingWindowExclusions,
        availableAircraftCount, neoAvailableAircraftCount, neoAircraftConfigCapacities, availableFtdCount, availableCptCount,
        timezoneOffset, showDepartureDensityOverlay, tileStatusSettings,
        sctEvents, formationCallsigns, courseColors,
        phraseBank, cancellationCodes,
        masterCurrencies, currencyRequirements,
        organisationSettings,
        coursePriorities, coursePercentages,
    ]);

    // Baseline schedule state
    const [baselineSchedules, setBaselineSchedules] = useState<Record<string, ScheduleEvent[]>>({});
    const activeBaselineKey = getDailySnapshotKey(date);

    // Alerts data state: { [date]: { [eventId]: alertEntry } }
    const [alertsDataByDate, setAlertsDataByDate] = useState<Record<string, Record<string, any>>>({});

    const isDirtyRef = useRef<() => boolean>(() => false);
    const onSaveRef = useRef<() => void>(() => {});
    const onDiscardRef = useRef<() => void>(() => {});

    const buildResources = useMemo(() => {
        // Stage 3: resource rows may come from Platform Configuration only when
        // the selected location pool explicitly opts in. Otherwise V2 behaviour
        // remains unchanged.
        const pc21Count = configuredAirframeCount;

        // Check for deployment events that overlap with the current date
        let deploymentCount = 0;

        console.log('buildResources - Current view:', activeView, 'Current date:', date);

        if (activeView === 'Program Schedule' || activeView === 'DailyFlyingProgram' || activeView === 'InstructorSchedule' || activeView === 'TraineeSchedule') {
            // Match the rendered schedule source: deployment rows come from the
            // current date's saved events so stale/deleted deployments on other
            // dates cannot leave phantom Deployed rows behind.
            const currentDateEvents: ScheduleEvent[] = publishedSchedules[date] || [];
            const deploymentIds = new Set<string>();
            currentDateEvents.forEach(event => {
                if (!event.date || typeof event.date !== 'string' || !event.date.match(/^\d{4}-\d{2}-\d{2}$/)) {
                    console.warn('[DeploymentCount] Event has invalid date format, skipping:', event.id, event.date);
                    return;
                }
                if (event.type !== 'deployment' || event.isCancelled) return;
                deploymentIds.add(event.id);
            });

            deploymentCount = deploymentIds.size;
        } else if (['NextDayBuild', 'Priorities', 'ProgramData', 'NextDayInstructorSchedule', 'NextDayTraineeSchedule'].includes(activeView)) {
            // For next day build, check if any deployment exists in nextDayBuildEvents
            const deploymentEvents = nextDayBuildEvents.filter(event => event.type === 'deployment');
            deploymentCount = deploymentEvents.length;
        }


        // Build PC-21 resources, replacing the last N with "Deployed X" if needed
        const pc21Resources = Array.from({ length: pc21Count }, (_, i) => {
            const deploymentIndex = pc21Count - i;
            if (deploymentIndex <= deploymentCount) {
                const deployNum = deploymentCount - deploymentIndex + 1;
                return `Deployed ${deployNum}`;
            }
            return `PC-21 ${i + 1}`;
        });

        // Calculate dynamic STBY line count based on actual STBY events
        let stbyLineCount = configuredStandbyCount; // Minimum configured STBY lines

        // For next day build views, check how many STBY lines are actually used
        if (['NextDayBuild', 'Priorities', 'ProgramData', 'NextDayInstructorSchedule', 'NextDayTraineeSchedule', 'BuildAnalysis'].includes(activeView)) {
            const stbyEvents = nextDayBuildEvents.filter(e =>
                e.resourceId.startsWith('STBY') || e.resourceId.startsWith('BNF-STBY')
            );

            if (stbyEvents.length > 0) {
                // Find the highest STBY line number used
                const maxStbyLine = Math.max(...stbyEvents.map(e => {
                    const match = e.resourceId.match(/STBY (\d+)/);
                    return match ? parseInt(match[1]) : 0;
                }));

                stbyLineCount = Math.max(configuredStandbyCount, maxStbyLine); // At least configured minimum, or more if needed
            }
        } else {
            // For published schedules, check the events for that date
            const eventsForDate = publishedSchedules[date] || [];
            const stbyEvents = eventsForDate.filter(e =>
                e.resourceId.startsWith('STBY') || e.resourceId.startsWith('BNF-STBY')
            );

            if (stbyEvents.length > 0) {
                const maxStbyLine = Math.max(...stbyEvents.map(e => {
                    const match = e.resourceId.match(/STBY (\d+)/);
                    return match ? parseInt(match[1]) : 0;
                }));

                stbyLineCount = Math.max(configuredStandbyCount, maxStbyLine);
            }
        }

        const allResources = [
            ...pc21Resources,
            'Duty Sup',
            'TWR DI',
            ...Array.from({ length: stbyLineCount }, (_, i) => `STBY ${i + 1}`),
            ...Array.from({ length: configuredFtdCount }, (_, i) => `FTD ${i + 1}`),
            ...Array.from({ length: configuredCptCount }, (_, i) => `CPT ${i + 1}`),
            ...Array.from({ length: configuredGroundCount }, (_, i) => `Ground ${i + 1}`),
        ];

        console.log('Built all resources:', allResources, 'STBY lines:', stbyLineCount);
        return allResources;
    }, [
        configuredAirframeCount,
        configuredFtdCount,
        configuredCptCount,
        configuredStandbyCount,
        configuredGroundCount,
        date,
        activeView,
        publishedSchedules,
        nextDayBuildEvents,
    ]);

    // Filter resources to only show those with events (for schedule views)
    const getFilteredResources = useCallback((events: ScheduleEvent[], allResources: string[]) => {
        // Safety check: if no events, return empty array
        if (!events || events.length === 0) {
            console.log('No events, returning empty resources');
            return [];
        }

        // Map each event to its resource category label
        const resourceLabels: string[] = [];

        for (const event of events) {
            // Safety check for event and resourceId
            if (!event || !event.resourceId) {
                console.warn('Skipping invalid event:', event);
                continue;
            }

            const resourceId = event.resourceId;

            // Determine the category for this event
            let category = 'Unknown';
            if (resourceId.startsWith('PC-21') || resourceId.startsWith('Deployed')) {
                category = 'PC-21';
            } else if (resourceId === 'Duty Sup') {
                category = 'Duty Sup';
            } else if (resourceId.startsWith('STBY') || resourceId.startsWith('BNF-STBY')) {
                category = 'STBY';
            } else if (resourceId.startsWith('FTD')) {
                category = 'FTD';
            } else if (resourceId.startsWith('CPT')) {
                category = 'CPT';
            } else if (resourceId.startsWith('Ground')) {
                category = 'Ground';
            } else {
                category = resourceId; // Fallback to actual resource ID
            }

            resourceLabels.push(category);
        }

        console.log('Resource labels (one per event):', resourceLabels.slice(0, 30));
        return resourceLabels;
    }, []);

