    const handleBuildDateChange = (direction: 'prev' | 'next') => {
        const currentDate = new Date(buildDfpDate + 'T00:00:00Z');
        if (direction === 'prev') {
            currentDate.setUTCDate(currentDate.getUTCDate() - 1);
        } else {
            currentDate.setUTCDate(currentDate.getUTCDate() + 1);
        }
        // Clear build events when navigating to a different date to prevent ghost tiles
        setNextDayBuildEvents([]);
        setBuildDfpDate(getLocalDateString(currentDate));
    };

    const handleAddTrainee = useCallback((newTrainee: Trainee) => {
        setTraineesData(prev => [...prev, newTrainee]);

        // Initialize Individual LMP based on trainee's lmpType.
        // If trainee.lmpType is not set, fall back to the course's lmpType (from courses state).
        let lmpType = newTrainee.lmpType || '';
        if (!lmpType || lmpType === 'BPC+IPC') {
            const courseObj = courses.find(c => c.name === newTrainee.course);
            if (courseObj?.lmpType) lmpType = courseObj.lmpType;
        }
        if (!lmpType) lmpType = 'BPC+IPC';
        const masterLMP = syllabusDetails.filter(item => {
            if (lmpType === 'BPC+IPC') {
                return (!item.lmpType || item.lmpType === 'Master LMP') && item.type !== 'Academics';
            }
            return item.courses && item.courses.includes(lmpType);
        });

        if (masterLMP.length > 0) {
            setTraineeLMPs(prev => {
                const newLMPs = new Map(prev);
                newLMPs.set(newTrainee.fullName, mergeIndividualLmpWithMaster(newLMPs.get(newTrainee.fullName), masterLMP));
                console.log(`[Individual LMP] Initialized ${newTrainee.fullName}'s Individual LMP with ${lmpType} (${masterLMP.length} events)`);
                return newLMPs;
            });
        }

        setSuccessMessage('New Trainee Added!');
    }, [syllabusDetails]);

    // Shared trainee update handler — updates in-memory state AND persists to DB if record is a DB trainee
    const handleUpdateTrainee = useCallback(async (data: Trainee) => {
        console.log('📝 [APP] handleUpdateTrainee called');
        console.log('📝 [APP] Trainee data received:', {
            id: (data as any).id,
            idNumber: data.idNumber,
            name: data.name,
            _dataSource: (data as any)._dataSource,
            unavailability: data.unavailability,
            unavailabilityLength: data.unavailability?.length || 0
        });

        // Update in-memory state immediately
        setTraineesData(prev => prev.map(t => t.idNumber === data.idNumber ? data : t));

        // If this is a DB trainee, persist changes to the database
        const dbId = (data as any).id;
        console.log('📝 [APP] DB ID:', dbId);
        console.log('📝 [APP] Is DB trainee?', dbId && (data as any)._dataSource === 'database');

        if (dbId && (data as any)._dataSource === 'database') {
            try {
                const patchBody = {
                    name: data.name,
                    fullName: data.fullName,
                    rank: data.rank,
                    course: data.course,
                    lmpType: data.lmpType,
                    academicLmpType: (data as any).academicLmpType || '',
                    unit: data.unit,
                    flight: data.flight,
                    location: data.location,
                    service: data.service,
                    seatConfig: data.seatConfig,
                    isPaused: data.isPaused,
                    traineeCallsign: data.traineeCallsign,
                    primaryInstructor: data.primaryInstructor,
                    secondaryInstructor: data.secondaryInstructor,
                    phoneNumber: data.phoneNumber,
                    email: data.email,
                    permissions: data.permissions || [],
                    unavailability: data.unavailability || [],
                };

                console.log('📝 [APP] PATCH body to send:', patchBody);
                console.log('📝 [APP] PATCH unavailability field:', patchBody.unavailability);

                const response = await fetch(`/api/trainees/${dbId}`, {
                    method: 'PATCH',
                    headers: { 'Content-Type': 'application/json' },
                    credentials: 'include',
                    body: JSON.stringify({
                        name: data.name,
                        fullName: data.fullName,
                        rank: data.rank,
                        course: data.course,
                        lmpType: data.lmpType,
                        academicLmpType: (data as any).academicLmpType || '',
                        unit: data.unit,
                        flight: data.flight,
                        location: data.location,
                        service: data.service,
                        seatConfig: data.seatConfig,
                        isPaused: data.isPaused,
                        traineeCallsign: data.traineeCallsign,
                        primaryInstructor: data.primaryInstructor,
                        secondaryInstructor: data.secondaryInstructor,
                        phoneNumber: data.phoneNumber,
                        email: data.email,
                        permissions: data.permissions || [],
                        unavailability: data.unavailability || [],
                    })
                });

                console.log('📝 [APP] PATCH response status:', response.status);
                console.log('📝 [APP] PATCH response ok:', response.ok);

                if (response.ok) {
                    console.log(`✅ DB trainee updated: ${data.name}`);
                    const responseData = await response.json();
                    console.log('📝 [APP] Response data:', responseData);
                } else {
                    const err = await response.text();
                    console.error(`❌ Failed to update DB trainee ${data.name}:`, err);
                    console.error('❌ Response status:', response.status);
                }
            } catch (err) {
                console.error(`❌ Error updating DB trainee ${data.name}:`, err);
            }
        } else {
            console.log('⚠️ [APP] Skipping DB update - not a DB trainee or no ID');
        }
    }, []);

    const buildRemedialPackageLmp = (
        originalTraineeLMP: SyllabusItemDetail[],
        eventToRemediate: SyllabusItemDetail,
        newEvents: { id?: string, code?: string, type: 'TUT' | 'FTD' | 'Flight', duration: number, instructor: string, dayNight?: 'Day' | 'Night' | 'Day/Night' }[]
    ): SyllabusItemDetail[] | null => {
        // Req 3.2, 3.3.1-3.3.3: Create all new remedial items and the re-fly event.
        let lastNewEventId = eventToRemediate.id;
        const remedialPackageItems: SyllabusItemDetail[] = [];
        const baseEventCode = getRemedialBaseEventCode(eventToRemediate);
        const typeCounts = { TUT: 0, FTD: 0, Flight: 0 };
        const { completedAt: _completedAt, isComplete: _isComplete, completed: _completed, ...remedialTemplate } = eventToRemediate as SyllabusItemDetail & { isComplete?: boolean; completed?: boolean };

        newEvents.forEach((remEvent) => {
            let codeSuffix = '';
            let type: SyllabusItemDetail['type'] = 'Flight';
            typeCounts[remEvent.type]++;
            if (remEvent.type === 'TUT') { codeSuffix = `RT${typeCounts.TUT}`; type = 'Ground School'; }
            else if (remEvent.type === 'FTD') { codeSuffix = `RFTD${typeCounts.FTD}`; type = 'FTD'; }
            else if (remEvent.type === 'Flight') { codeSuffix = `RF${typeCounts.Flight}`; type = 'Flight'; }

            const remedialCode = remEvent.code || `${baseEventCode}-${codeSuffix}`;

            const newItem: SyllabusItemDetail = {
                ...remedialTemplate,
                id: remedialCode, code: remedialCode,
                isRemedial: true, // Req 2.3.3
                completedAt: null,
                eventDescription: remedialCode,
                module: 'Remedial', prerequisites: [lastNewEventId],
                dayNight: remEvent.dayNight || eventToRemediate.dayNight || 'Day',
                duration: remEvent.duration, flightOrSimHours: remEvent.duration,
                totalEventHours: remEvent.duration + (type === 'Ground School' ? 0.25 : 1.0), type,
                prerequisitesGround: [], prerequisitesFlying: [],
                preFlightTime: type === 'Ground School' ? 0.25 : (type === 'FTD' ? 0.5 : 1.0),
                postFlightTime: type === 'Ground School' ? 0 : (type === 'FTD' ? 0.5 : 0.5),
                location: '', methodOfDelivery: [], methodOfAssessment: [], resourcesPhysical: [], resourceNumber: 0, resourcesHuman: [remEvent.instructor], eventDetailsCommon: [], eventDetailsSortie: [],
            };
            remedialPackageItems.push(newItem);
            lastNewEventId = newItem.id;
        });

        const reFlyCode = `${baseEventCode}-RRF1`;
        const reFlyEvent: SyllabusItemDetail = {
            ...remedialTemplate, id: reFlyCode, code: reFlyCode,
            isRemedial: true,
            completedAt: null,
            eventDescription: reFlyCode, module: 'Remedial',
            prerequisites: [lastNewEventId], prerequisitesGround: [], prerequisitesFlying: [],
        };
        remedialPackageItems.push(reFlyEvent);

        const newRemedialIds = new Set(remedialPackageItems.map(item => item.id));
        const isSameRemedialPackageItem = (item: SyllabusItemDetail): boolean =>
            isRemedialSyllabusItem(item) && getRemedialBaseEventCode(item) === baseEventCode;
        const cleanedLmp: SyllabusItemDetail[] = originalTraineeLMP
            .filter(item => !newRemedialIds.has(item.id) && !isSameRemedialPackageItem(item))
            .map(item => ({ ...item, prerequisites: [...(item.prerequisites || [])] }));

        const insertionIndex = cleanedLmp.findIndex(item =>
            item.id === eventToRemediate.id ||
            item.code === eventToRemediate.code ||
            (!!eventToRemediate.masterEventId && item.masterEventId === eventToRemediate.masterEventId)
        );

        if (insertionIndex === -1) {
            console.error("Critical error: Failed to find insertion point. LMP not modified.", {
                eventToRemediateId: eventToRemediate.id,
                eventToRemediateCode: eventToRemediate.code,
                eventToRemediateMasterId: eventToRemediate.masterEventId,
            });
            return null;
        }

        const anchorAfterMasterEventId = getMasterEventId(cleanedLmp[insertionIndex]);
        const anchorBeforeMasterEventId = getMasterEventId(cleanedLmp.slice(insertionIndex + 1).find(item => !isLmpOverlayItem(item)) || {});
        const anchoredRemedialItems = remedialPackageItems.map((item, index) => ({
            ...item,
            lmpSource: 'remedial' as const,
            masterEventId: undefined,
            anchorAfterMasterEventId,
            anchorBeforeMasterEventId: anchorBeforeMasterEventId || undefined,
            anchorPolicy: 'between' as const,
            orderKey: `${createLmpOrderKey(insertionIndex)}.${String(index + 1).padStart(3, '0')}`,
            placementNeedsReview: !anchorAfterMasterEventId && !anchorBeforeMasterEventId,
        }));

        cleanedLmp.splice(insertionIndex + 1, 0, ...anchoredRemedialItems);

        // CRITICAL FIX: Update ALL subsequent events that depend on the failed event
        // Previously only updated the first one, causing events beyond the first to be schedulable
        // before completing the remedial package
        const originalEventRefs = [eventToRemediate.id, eventToRemediate.code, eventToRemediate.masterEventId].filter(Boolean);
        const subsequentEvents = cleanedLmp.filter(item =>
            item.prerequisites.some(prerequisite => originalEventRefs.includes(prerequisite))
        );

        subsequentEvents.forEach(subsequentEvent => {
            const prereqIndex = subsequentEvent.prerequisites.findIndex(prerequisite => originalEventRefs.includes(prerequisite));
            if (prereqIndex !== -1) {
                const oldPrereq = subsequentEvent.prerequisites[prereqIndex];
                subsequentEvent.prerequisites[prereqIndex] = reFlyEvent.id;
                console.log(`✅ Updated prerequisite for ${subsequentEvent.code}: ${oldPrereq} → ${reFlyEvent.id}`);
            }
        });

        return cleanedLmp;
    };

    const getLmpTypeForTrainee = (trainee: Trainee): string => {
        if (trainee.lmpType) return trainee.lmpType;
        if (trainee.course && trainee.course.toUpperCase().startsWith('FIC')) return 'FIC';
        return 'BPC+IPC';
    };

    const persistTraineeLmp = async (trainee: Trainee, lmp: SyllabusItemDetail[], excludedCompletedEvents: string[] = []): Promise<SyllabusItemDetail[]> => {
        const matchedTrainee = allTraineesData.find((candidate: any) => candidate.fullName === trainee.fullName);
        const traineeDbId = (trainee as any).id || (matchedTrainee as any)?.id;
        if (!traineeDbId) {
            throw new Error(`Cannot save Individual LMP: trainee database record not found for ${trainee.fullName}`);
        }

        const excludedCompletedSet = new Set(excludedCompletedEvents.filter(Boolean));
        const completedFromLmp = lmp
            .filter(item => item.completedAt)
            .map(item => item.id || item.code)
            .filter((eventId): eventId is string => Boolean(eventId) && !excludedCompletedSet.has(eventId));
        const completedFromScores = (scores.get(trainee.fullName) || [])
            .map(score => score.event)
            .filter((eventId): eventId is string => Boolean(eventId) && !excludedCompletedSet.has(eventId));
        const completedEventIds = Array.from(new Set([...completedFromLmp, ...completedFromScores]));

        const apiBase = getApiBaseUrl();
        const response = await fetch(`${apiBase}/trainees/${encodeURIComponent(traineeDbId)}/lmp`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            credentials: 'include',
            body: JSON.stringify({
                traineeFullName: trainee.fullName,
                lmpType: getLmpTypeForTrainee(trainee),
                events: lmp,
                completedEventIds,
            }),
        });

        if (!response.ok) {
            const errorText = await response.text();
            throw new Error(errorText || `Failed to persist Individual LMP (${response.status})`);
        }

        const saved = await response.json();
        const savedEvents = saved?.lmp?.events;
        if (!Array.isArray(savedEvents) || savedEvents.length === 0) {
            throw new Error('Individual LMP save response did not include persisted events');
        }

        return savedEvents;
    };

    const deletePersistedIndividualLmpEventRecords = async (trainee: Trainee, item: SyllabusItemDetail): Promise<string[]> => {
        const matchedTrainee = allTraineesData.find((candidate: any) => candidate.fullName === trainee.fullName);
        const traineeDbId = (trainee as any).id || (matchedTrainee as any)?.id;
        if (!traineeDbId) {
            throw new Error(`Cannot delete persisted event records: trainee database record not found for ${trainee.fullName}`);
        }

        const eventRefs = Array.from(new Set([
            item.id,
            item.code,
            buildPt051EventFromLmpItem(trainee, item).id,
        ].filter(Boolean) as string[]));
        const eventCodeRefs = new Set([item.id, item.code].filter(Boolean) as string[]);
        const apiBase = getApiBaseUrl();

        const scoreResponse = await fetch(`${apiBase}/scores/trainee/${encodeURIComponent(traineeDbId)}/events`, {
            method: 'DELETE',
            credentials: 'include',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ events: Array.from(eventCodeRefs) }),
        });
        if (!scoreResponse.ok) {
            const errorText = await scoreResponse.text().catch(() => '');
            throw new Error(errorText || `Failed to delete score records for ${item.code} (${scoreResponse.status})`);
        }

        const performanceResponse = await fetch(`${apiBase}/trainee-performance?traineeFullName=${encodeURIComponent(trainee.fullName)}&limit=2000`, {
            credentials: 'include',
        });
        if (performanceResponse.ok) {
            const rows = await performanceResponse.json();
            if (Array.isArray(rows)) {
                const performanceEventIds = Array.from(new Set(rows
                    .filter((assessment: Pt051Assessment) =>
                        eventRefs.includes(assessment.eventId) ||
                        eventRefs.includes(assessment.id) ||
                        eventCodeRefs.has(assessment.flightNumber)
                    )
                    .map((assessment: Pt051Assessment) => assessment.eventId)
                    .filter(Boolean)));

                for (const eventId of performanceEventIds) {
                    const deleteResponse = await fetch(`${apiBase}/trainee-performance/${encodeURIComponent(eventId)}`, {
                        method: 'DELETE',
                        credentials: 'include',
                    });
                    if (!deleteResponse.ok) {
                        const errorText = await deleteResponse.text().catch(() => '');
                        throw new Error(errorText || `Failed to delete PT-051 record for ${item.code} (${deleteResponse.status})`);
                    }
                }
            }
        } else {
            console.warn(`[Individual LMP] Could not scan PT-051 records while deleting ${item.code}:`, await performanceResponse.text().catch(() => ''));
        }

        setScores(prev => {
            const traineeScores = prev.get(trainee.fullName) || [];
            const updatedScores = traineeScores.filter(score => !eventCodeRefs.has(score.event));
            if (updatedScores.length === traineeScores.length) return prev;
            const updated = new Map(prev);
            updated.set(trainee.fullName, updatedScores);
            return updated;
        });
        setPt051Assessments(prev => {
            const updated = new Map(prev);
            Array.from(updated.entries()).forEach(([key, assessment]) => {
                if (
                    assessment.traineeFullName === trainee.fullName &&
                    (
                        eventRefs.includes(assessment.eventId) ||
                        eventRefs.includes(assessment.id) ||
                        eventCodeRefs.has(assessment.flightNumber)
                    )
                ) {
                    updated.delete(key);
                }
            });
            return updated;
        });
        setLoadedPt051Keys(prev => {
            const updated = new Set(prev);
            eventRefs.forEach(eventRef => updated.delete(`${eventRef}-${trainee.fullName}`));
            return updated;
        });

        return eventRefs;
    };

    const handleSaveRemedialPackage = async (
        trainee: Trainee,
        eventToRemediate: SyllabusItemDetail,
        newEvents: { id?: string, code?: string, type: 'TUT' | 'FTD' | 'Flight', duration: number, instructor: string }[]
    ) => {
        const originalTraineeLMP = traineeLMPs.get(trainee.fullName);
        if (!originalTraineeLMP) {
            console.error("LMP not found for trainee:", trainee.fullName);
            setShowInfoNotification(`Could not add remedial package: Individual LMP not found for ${trainee.fullName}.`);
            return;
        }

        const updatedLmp = buildRemedialPackageLmp(originalTraineeLMP, eventToRemediate, newEvents);
        if (!updatedLmp) {
            setShowInfoNotification('Could not add remedial package: failed to find the selected event in the Individual LMP.');
            return;
        }

        setTraineeLMPs(prevLMPs => {
            const newLMPs = new Map(prevLMPs);
            newLMPs.set(trainee.fullName, updatedLmp);
            return newLMPs;
        });

        try {
            const persistedLmp = await persistTraineeLmp(trainee, updatedLmp);
            setTraineeLMPs(prevLMPs => {
                const newLMPs = new Map(prevLMPs);
                newLMPs.set(trainee.fullName, persistedLmp);
                return newLMPs;
            });
            void loadPersistedTraineeLmp(trainee);
            setShowAddRemedialPackage(false);
            setSuccessMessage('Remedial package added to trainee LMP.');
        } catch (error) {
            console.error('[Individual LMP] Failed to persist remedial package:', error);
            void showDarkAlert(
                `Remedial package was added locally, but could not be saved to the database. Please try again before refreshing.\n\n${error instanceof Error ? error.message : String(error)}`,
                'Individual LMP Save Failed',
                'error'
            );
        }
    };

    const handleDeleteRemedialLmpItem = async (trainee: Trainee, item: SyllabusItemDetail): Promise<boolean> => {
        const confirmed = await showDarkConfirm(
            `Delete remedial event ${item.code} from ${trainee.fullName}'s Individual LMP?\n\nThis will remove the remedial event from the package sequence and cannot be undone.`,
            'Delete Remedial Event',
            'warning'
        );
        if (!confirmed) return false;

        const originalTraineeLMP = traineeLMPs.get(trainee.fullName);
        if (!originalTraineeLMP) {
            await showDarkAlert(`Could not delete ${item.code}: Individual LMP not found for ${trainee.fullName}.`, 'Individual LMP Delete Failed', 'error');
            return false;
        }

        const itemId = item.id || item.code;
        const itemCode = item.code || item.id;
        const updatedLmp = originalTraineeLMP
            .filter(lmpItem => (lmpItem.id || lmpItem.code) !== itemId && (lmpItem.code || lmpItem.id) !== itemCode)
            .map(lmpItem => ({
                ...lmpItem,
                prerequisites: (lmpItem.prerequisites || []).filter(prerequisite => prerequisite !== itemId && prerequisite !== itemCode),
            }));

        try {
            const deletedEventRefs = await deletePersistedIndividualLmpEventRecords(trainee, item);
            const persistedLmp = await persistTraineeLmp(trainee, updatedLmp, deletedEventRefs);
            setTraineeLMPs(prevLMPs => {
                const newLMPs = new Map(prevLMPs);
                newLMPs.set(trainee.fullName, persistedLmp);
                return newLMPs;
            });
            logAudit(
                'Individual LMP',
                'Delete',
                `Deleted remedial event ${item.code} from ${trainee.fullName}`,
                [
                    `Event: ${item.code}`,
                    `Description: ${item.eventDescription || 'Unknown'}`,
                    `Trainee: ${trainee.rank ? `${trainee.rank} ` : ''}${trainee.name}`,
                    `Course: ${trainee.course || 'Unknown'}`,
                    `LMP events: ${originalTraineeLMP.length} to ${persistedLmp.length}`,
                ].join('; ')
            );
            setSuccessMessage(`Deleted remedial event ${item.code}.`);
            return true;
        } catch (error) {
            console.error('[Individual LMP] Failed to delete remedial item:', error);
            await showDarkAlert(
                `Remedial event ${item.code} could not be deleted from the database. It has not been removed locally.\n\n${error instanceof Error ? error.message : String(error)}`,
                'Individual LMP Delete Failed',
                'error'
            );
            return false;
        }
    };

    const handleInsertCustomLmpEvent = async (trainee: Trainee, request: InsertLmpEventRequest): Promise<boolean> => {
        const originalTraineeLMP = traineeLMPs.get(trainee.fullName);
        if (!originalTraineeLMP || originalTraineeLMP.length === 0) {
            await showDarkAlert(`Could not insert ${request.label}: Individual LMP not found for ${trainee.fullName}.`, 'Insert Event Failed', 'error');
            return false;
        }

        const insertionIndex = originalTraineeLMP.findIndex(item => (
            (item.id || item.code) === request.followsEventId ||
            (item.code || item.id) === request.followsEventId
        ));
        if (insertionIndex === -1) {
            await showDarkAlert('Could not insert event: the selected follow-on event was not found in the Individual LMP.', 'Insert Event Failed', 'error');
            return false;
        }

        const cleanedLabel = request.label.trim().slice(0, 8);
        const existingCodes = new Set(originalTraineeLMP.map(item => String(item.code || item.id || '').toUpperCase()));
        let sequence = 1;
        let eventCode = cleanedLabel;
        while (existingCodes.has(eventCode.toUpperCase())) {
            const suffix = String(sequence);
            eventCode = `${cleanedLabel.slice(0, Math.max(1, 8 - suffix.length))}${suffix}`;
            sequence++;
        }

        const followsItem = originalTraineeLMP[insertionIndex];
        const nextMasterItem = originalTraineeLMP.slice(insertionIndex + 1).find(item => !isLmpOverlayItem(item));
        const physicalResources = Array.from({ length: request.resourceCount }, (_, index) => (
            request.resourceCount === 1 ? 'Aircraft' : `Aircraft ${index + 1}`
        ));

        const newItem: SyllabusItemDetail = {
            id: `custom-${Date.now()}-${eventCode}`,
            code: eventCode,
            phase: followsItem.phase || '',
            module: 'Inserted Event',
            dayNight: request.dayNight,
            eventDescription: eventCode,
            prerequisites: [followsItem.id || followsItem.code].filter(Boolean),
            prerequisitesGround: [],
            prerequisitesFlying: [],
            eventDetailsCommon: [],
            eventDetailsSortie: [],
            totalEventHours: request.totalEventHours,
            flightOrSimHours: request.flightOrSimHours,
            duration: request.duration,
            preFlightTime: request.preFlightTime,
            postFlightTime: request.postFlightTime,
            type: request.eventType.syllabusType,
            sortieType: request.eventType.syllabusType === 'Flight' ? 'Dual' : undefined,
            methodOfDelivery: [],
            methodOfAssessment: [],
            resourcesPhysical: physicalResources,
            resourceNumber: request.resourceCount,
            resourceCount: request.resourceCount,
            acceptableAircraftConfigs: [ANY_AIRCRAFT_CONFIG],
            resourcesHuman: request.eventType.syllabusType === 'Academics' ? [] : ['QFI', 'Trainee'],
            completedAt: null,
            masterEventId: undefined,
            lmpSource: 'custom',
            orderKey: `${createLmpOrderKey(insertionIndex)}.${String(Date.now()).slice(-6)}`,
            anchorAfterMasterEventId: getMasterEventId(followsItem),
            anchorBeforeMasterEventId: nextMasterItem ? getMasterEventId(nextMasterItem) : undefined,
            anchorPolicy: 'between',
            userLockedPosition: true,
            placementNeedsReview: false,
            location: followsItem.location || '',
            courses: followsItem.courses || [],
            lmpType: followsItem.lmpType,
        } as SyllabusItemDetail & { resourceCount: number };

        const updatedLmp = [
            ...originalTraineeLMP.slice(0, insertionIndex + 1),
            newItem,
            ...originalTraineeLMP.slice(insertionIndex + 1),
        ];

        try {
            const persistedLmp = await persistTraineeLmp(trainee, updatedLmp);
            setTraineeLMPs(prevLMPs => {
                const newLMPs = new Map(prevLMPs);
                newLMPs.set(trainee.fullName, persistedLmp);
                return newLMPs;
            });
            logAudit(
                'Individual LMP',
                'Insert',
                `Inserted event ${eventCode} into ${trainee.fullName}'s Individual LMP`,
                [
                    `Event: ${eventCode}`,
                    `Type: ${request.eventType.label}`,
                    `Day/Night: ${request.dayNight}`,
                    `Resources: ${request.resourceCount}`,
                    `Follows: ${followsItem.code}`,
                    `Trainee: ${trainee.rank ? `${trainee.rank} ` : ''}${trainee.name}`,
                ].join('; ')
            );
            setSuccessMessage(`Inserted event ${eventCode} into Individual LMP.`);
            return true;
        } catch (error) {
            console.error('[Individual LMP] Failed to insert custom event:', error);
            await showDarkAlert(
                `The event was not saved to the database, so it has not been inserted.\n\n${error instanceof Error ? error.message : String(error)}`,
                'Insert Event Failed',
                'error'
            );
            return false;
        }
    };

    const handleUpdateIndividualLmpItem = async (
        trainee: Trainee,
        originalItem: SyllabusItemDetail,
        updatedItem: SyllabusItemDetail
    ): Promise<boolean> => {
        const originalTraineeLMP = traineeLMPs.get(trainee.fullName);
        if (!originalTraineeLMP || originalTraineeLMP.length === 0) {
            await showDarkAlert(`Could not update ${originalItem.code}: Individual LMP not found for ${trainee.fullName}.`, 'Individual LMP Save Failed', 'error');
            return false;
        }

        const originalId = originalItem.id || originalItem.code;
        const originalCode = originalItem.code || originalItem.id;
        const updatedCode = String(updatedItem.code || updatedItem.id || '').trim().toUpperCase();
        const duplicateCode = originalTraineeLMP.some(item => {
            const matchesOriginal = (item.id || item.code) === originalId || (item.code || item.id) === originalCode;
            if (matchesOriginal) return false;
            return String(item.code || item.id || '').trim().toUpperCase() === updatedCode;
        });
        if (duplicateCode) {
            await showDarkAlert(`Could not update ${originalItem.code}: another Individual LMP event already uses ${updatedItem.code}.`, 'Individual LMP Save Failed', 'error');
            return false;
        }

        const updatedLmp = originalTraineeLMP.map(item => {
            const matchesOriginal = (item.id || item.code) === originalId || (item.code || item.id) === originalCode;
            if (matchesOriginal) return updatedItem;
            return {
                ...item,
                prerequisites: (item.prerequisites || []).map(prerequisite =>
                    prerequisite === originalCode ? updatedItem.code :
                    prerequisite === originalId ? (updatedItem.id || updatedItem.code) :
                    prerequisite
                ),
                prerequisitesGround: (item.prerequisitesGround || []).map(prerequisite =>
                    prerequisite === originalCode ? updatedItem.code :
                    prerequisite === originalId ? (updatedItem.id || updatedItem.code) :
                    prerequisite
                ),
                prerequisitesFlying: (item.prerequisitesFlying || []).map(prerequisite =>
                    prerequisite === originalCode ? updatedItem.code :
                    prerequisite === originalId ? (updatedItem.id || updatedItem.code) :
                    prerequisite
                ),
            };
        });

        if (!updatedLmp.some(item => (item.id || item.code) === (updatedItem.id || updatedItem.code))) {
            await showDarkAlert(`Could not update ${originalItem.code}: selected event was not found in the Individual LMP.`, 'Individual LMP Save Failed', 'error');
            return false;
        }

        try {
            const persistedLmp = await persistTraineeLmp(trainee, updatedLmp);
            setTraineeLMPs(prevLMPs => {
                const newLMPs = new Map(prevLMPs);
                newLMPs.set(trainee.fullName, persistedLmp);
                return newLMPs;
            });
            logAudit(
                'Individual LMP',
                'Edit',
                `Edited event ${originalItem.code} in ${trainee.fullName}'s Individual LMP`,
                [
                    `Original Event: ${originalItem.code}`,
                    `Updated Event: ${updatedItem.code}`,
                    `Type: ${updatedItem.type}`,
                    `Day/Night: ${updatedItem.dayNight}`,
                    `Duration: ${updatedItem.duration}`,
                    `Resource Number: ${updatedItem.resourceNumber ?? 0}`,
                    `Trainee: ${trainee.rank ? `${trainee.rank} ` : ''}${trainee.name}`,
                ].join('; ')
            );
            setSuccessMessage(`Updated ${updatedItem.code} in Individual LMP.`);
            return true;
        } catch (error) {
            console.error('[Individual LMP] Failed to update event:', error);
            await showDarkAlert(
                `The event was not saved to the database, so it has not been updated.\n\n${error instanceof Error ? error.message : String(error)}`,
                'Individual LMP Save Failed',
                'error'
            );
            return false;
        }
    };

