    const handleAuthorise = async (eventId: string, notes: string, role: 'autho' | 'captain', isVerbal: boolean, selectedPersonName: string) => {
        const authEventDate = eventForAuth?.date || Object.entries(publishedSchedules).find(([, eventsList]) => (
            (eventsList as ScheduleEvent[]).some(e => e.id === eventId)
        ))?.[0];
        if (isPastDfpDate(authEventDate)) {
            denyPastDfpEdit('authorise events');
            return;
        }
        // System freeze check - read directly from localStorage to avoid stale closure
        const _freezeRaw = localStorage.getItem('systemFreezeState');
        if (_freezeRaw) {
            const _freeze = JSON.parse(_freezeRaw);
            if (_freeze.isFrozen && !_freeze.allowedActions?.flightAuthorisation) {
                showDarkAlert('System is currently frozen. Flight Authorisation entries are not permitted during a system freeze.', 'System Frozen', 'error');
                return;
            }
        }
        const now = new Date().toISOString();
        const authoSigner = selectedPersonName; // Use the selected person's name, not current user

        let wasFullyAuthed = false;
        let eventThatWasUpdated: ScheduleEvent | null = null;
        let affectedScheduleDate: string | null = null;

        const normaliseAuthSigner = (value: string | undefined) => value?.trim().toLowerCase() || '';
        const isSameAuthSigner = (a: string | undefined, b: string | undefined) => {
            const left = normaliseAuthSigner(a);
            const right = normaliseAuthSigner(b);
            if (!left || !right) return false;
            return left === right || left.endsWith(` ${right}`) || right.endsWith(` ${left}`);
        };

        const updateEventAuth = (e: ScheduleEvent): ScheduleEvent => {
            if (e.id !== eventId) return e;

            const updatedEvent = { ...e, authNotes: notes, isVerbalAuth: isVerbal };

            if (role === 'autho') {
                updatedEvent.authoSignedBy = authoSigner;
                updatedEvent.authoSignedAt = now;
                if (isVerbal && updatedEvent.captainSignedBy) {
                    updatedEvent.authoSignedOnBehalfBy = updatedEvent.captainSignedOnBehalfBy || updatedEvent.captainSignedBy;
                } else {
                    delete updatedEvent.authoSignedOnBehalfBy;
                }
            } else if (role === 'captain') {
                updatedEvent.captainSignedBy = authoSigner;
                updatedEvent.captainSignedAt = now;
                if (isVerbal && updatedEvent.authoSignedBy) {
                    updatedEvent.captainSignedOnBehalfBy = updatedEvent.authoSignedOnBehalfBy || updatedEvent.authoSignedBy;
                } else {
                    delete updatedEvent.captainSignedOnBehalfBy;
                }
            }

            const isNowFullyAuthorized = !!(updatedEvent.authoSignedBy && updatedEvent.captainSignedBy);
            const isDualSignedVerbalAuth = !!(
                updatedEvent.isVerbalAuth &&
                isNowFullyAuthorized &&
                (
                    updatedEvent.authoSignedOnBehalfBy ||
                    updatedEvent.captainSignedOnBehalfBy ||
                    isSameAuthSigner(updatedEvent.authoSignedBy, updatedEvent.captainSignedBy)
                )
            );
            if (isDualSignedVerbalAuth) {
                const signer = updatedEvent.captainSignedOnBehalfBy ||
                    updatedEvent.authoSignedOnBehalfBy ||
                    updatedEvent.authoSignedBy ||
                    updatedEvent.captainSignedBy ||
                    authoSigner;
                updatedEvent.dualAuthSignedBy = signer;
                updatedEvent.dualAuthSignedAt = now;
                if (updatedEvent.captainSignedOnBehalfBy) {
                    updatedEvent.dualAuthSignedAnnotation = `${signer} signed PIC authorisation on behalf of ${updatedEvent.captainSignedBy} under verbal AUTH.`;
                } else if (updatedEvent.authoSignedOnBehalfBy) {
                    updatedEvent.dualAuthSignedAnnotation = `${signer} signed AUTHO authorisation on behalf of ${updatedEvent.authoSignedBy} under verbal AUTH.`;
                } else {
                    updatedEvent.dualAuthSignedAnnotation = `${signer} signed both AUTHO and PIC for this verbal authorisation.`;
                }
            } else {
                delete updatedEvent.authoSignedOnBehalfBy;
                delete updatedEvent.captainSignedOnBehalfBy;
                delete updatedEvent.dualAuthSignedBy;
                delete updatedEvent.dualAuthSignedAt;
                delete updatedEvent.dualAuthSignedAnnotation;
            }

            if (isNowFullyAuthorized) {
                wasFullyAuthed = true;
            }

            eventThatWasUpdated = updatedEvent;
            return updatedEvent;
        };

        const updateEventsInState = (eventsList: ScheduleEvent[]) => eventsList.map(updateEventAuth);

        const updatedPublishedSchedules = Object.fromEntries(
            Object.entries(publishedSchedules).map(([key, eventsList]) => {
                const updatedEventsForDate = (eventsList as ScheduleEvent[]).map(e => {
                    if (e.id === eventId) {
                        affectedScheduleDate = key;
                    }
                    return updateEventAuth(e);
                });
                return [key, updatedEventsForDate];
            })
        );

        if (!affectedScheduleDate && eventThatWasUpdated?.date) {
            affectedScheduleDate = eventThatWasUpdated.date;
            updatedPublishedSchedules[affectedScheduleDate] = (updatedPublishedSchedules[affectedScheduleDate] || []).map(updateEventAuth);
        }

        if (affectedScheduleDate && updatedPublishedSchedules[affectedScheduleDate]) {
            persistScheduleForDate(affectedScheduleDate, updatedPublishedSchedules[affectedScheduleDate]);
        }

        setEvents(prev => updateEventsInState(prev));
        setPublishedSchedules(updatedPublishedSchedules);

        if (eventThatWasUpdated) {
            setEventForAuth(eventThatWasUpdated);
        }

        // Only close the modal if NOT fully authorized
        // If fully authorized, keep modal open to show completion view
        if (role === 'captain' && !wasFullyAuthed && !isVerbal) {
            setShowAuthFlyout(false);
            setEventForAuth(null);
        }

        if (wasFullyAuthed) {
            setSuccessMessage(eventThatWasUpdated?.dualAuthSignedAnnotation || 'Flight Authorised!');
        }
    };

    const clearAuthorisationForEvent = (eventId: string) => {
        const authEventDate = eventForAuth?.date || Object.entries(publishedSchedules).find(([, eventsList]) => (
            (eventsList as ScheduleEvent[]).some(e => e.id === eventId)
        ))?.[0];
        if (isPastDfpDate(authEventDate)) {
            denyPastDfpEdit('clear authorisations');
            return;
        }
        let affectedScheduleDate: string | null = null;

        const clearAuthFields = (e: ScheduleEvent): ScheduleEvent => {
            if (e.id !== eventId) return e;
            const {
                authoSignedBy,
                authoSignedAt,
                authoSignedOnBehalfBy,
                captainSignedBy,
                captainSignedAt,
                captainSignedOnBehalfBy,
                isVerbalAuth,
                dualAuthSignedBy,
                dualAuthSignedAt,
                dualAuthSignedAnnotation,
                ...rest
            } = e;
            return { ...rest, authNotes: '' };
        };

        const updatedPublishedSchedules = Object.fromEntries(
            Object.entries(publishedSchedules).map(([key, eventsList]) => {
                const updatedEventsForDate = (eventsList as ScheduleEvent[]).map(e => {
                    if (e.id === eventId) affectedScheduleDate = key;
                    return clearAuthFields(e);
                });
                return [key, updatedEventsForDate];
            })
        );

        if (affectedScheduleDate && updatedPublishedSchedules[affectedScheduleDate]) {
            persistScheduleForDate(affectedScheduleDate, updatedPublishedSchedules[affectedScheduleDate]);
        }

        setEvents((prev) => prev.map(clearAuthFields));
        setPublishedSchedules(updatedPublishedSchedules);
        setEventForAuth(null);
        setShowAuthFlyout(false);
    };

    const handleBulkUpdateInstructors = useCallback((updatedInstructors: Instructor[]) => {
        const updatedMap = new Map(updatedInstructors.map(i => [i.idNumber, i]));

        setInstructorsData(prevInstructors => {
            const existingIds = new Set(prevInstructors.map(i => i.idNumber));
            const updatedExisting = prevInstructors.map(i => updatedMap.get(i.idNumber) || i);
            const newToAdd = updatedInstructors.filter(ui => !existingIds.has(ui.idNumber));
            return [...updatedExisting, ...newToAdd];
        });
    }, []);

